		private void RecPlayerCtrl_Main(global::Dpr.Battle.Logic.BTL_CLIENT.RECPLAYER_CONTROL ctrl) {
            if (m_myType != (byte)BtlClientType.BTL_CLIENT_TYPE_RECPLAY || ctrl.fLock || ctrl.fQuit)
                return;

            if (ctrl.maxTurnCount == 0)
                return;

            bool fUpdate = false;
            if (ctrl.fTurnIncrement)
            {
                ctrl.fTurnIncrement = false;
                if (ctrl.fChapterSkip)
                {
                    if (ctrl.skipTurnCount < ctrl.nextTurnCount)
                    {
                        ctrl.skipTurnCount++;
                        if (ctrl.skipTurnCount == ctrl.nextTurnCount)
                        {
                            ctrl.turnCount = ctrl.nextTurnCount;
                            if (m_viewCore != null)
                                m_viewCore.CMD_UpdateRecPlayerInput(ctrl.turnCount, ctrl.turnCount);
                        }
                    }
                    return;
                }

                if (ctrl.turnCount < ctrl.maxTurnCount && ctrl.seq == 0)
                {
                    ctrl.turnCount++;
                    if (ctrl.handlingTimer == 0)
                        ctrl.nextTurnCount = ctrl.turnCount;

                    fUpdate = true;
                }
            }

            if (ctrl.turnCount == 0)
                return;

            if (m_viewCore == null)
                return;

            switch ((SeqRecPlayerCtrl_Main)ctrl.seq)
            {
                case SeqRecPlayerCtrl_Main.SEQ_DEFAULT:
                    switch (m_viewCore.CMD_CheckRecPlayerInput())
                    {
                        case BattleViewBase.RecPlayerInput.REW:
                            if (ctrl.nextTurnCount > 1)
                            {
                                ctrl.nextTurnCount--;
                                fUpdate = true;
                            }
                            ctrl.handlingTimer = CHAPTER_CTRL_FRAMES;
                            break;

                        case BattleViewBase.RecPlayerInput.FF:
                            if (ctrl.nextTurnCount < ctrl.maxTurnCount)
                            {
                                ctrl.nextTurnCount++;
                                fUpdate = true;
                            }
                            ctrl.handlingTimer = CHAPTER_CTRL_FRAMES;
                            break;

                        case BattleViewBase.RecPlayerInput.STOP:
                            ctrl.ctrlCode = (byte)RecCtrlCode.RECCTRL_QUIT;
                            m_mainModule.StartFadeoutForRecPlay();
                            m_viewCore.CMD_RecPlayFadeOut_Start();
                            ctrl.fFadeOutStart = true;
                            ctrl.seq = (byte)SeqRecPlayerCtrl_Main.SEQ_FADEOUT;
                            ctrl.handlingTimer = 0;
                            m_viewCore.CMD_RecPlayer_StartQuit(ctrl.turnCount, BattleViewBase.RecPlayStopFlag.KEY);
                            m_viewCore.CMD_FadeOutBGM(30);
                            m_viewCore.CMD_StopAllSE();
                            break;
                    }

                    if (fUpdate)
                        m_viewCore.CMD_UpdateRecPlayerInput(ctrl.turnCount, ctrl.nextTurnCount);

                    if (ctrl.handlingTimer != 0)
                    {
                        ctrl.handlingTimer--;
                        if (ctrl.handlingTimer == 0)
                        {
                            ctrl.ctrlCode = (byte)RecCtrlCode.RECCTRL_CHAPTER;
                            m_mainModule.StartFadeoutForRecPlay();
                            m_viewCore.CMD_RecPlayFadeOut_Start();
                            m_viewCore.CMD_RecPlayer_StartSkipDisplay(ctrl.nextTurnCount);
                            ctrl.fFadeOutStart = true;
                            ctrl.seq = (byte)SeqRecPlayerCtrl_Main.SEQ_FADEOUT;
                            m_viewCore.CMD_FadeOutBGM(30);
                            m_viewCore.CMD_StopAllSE();
                        }
                    }
                    break;

                case SeqRecPlayerCtrl_Main.SEQ_FADEOUT:
                    if (m_viewCore.CMD_RecPlayFadeOut_Wait())
                    {
                        ctrl.fFadeOutDone = true;
                        ctrl.seq = (byte)SeqRecPlayerCtrl_Main.SEQ_STAY;
                    }
                    break;
            }
        }
