		private ushort AIItem_CheckUse(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp, global::Dpr.Battle.Logic.BTL_PARTY party) {
            byte[] useItemMemberCount = new byte[] { 6, 3, 2, 1 };
            byte aliveMemberCount = party.GetAliveMemberCount();

            if (bpp.CheckSick(WazaSick.WAZASICK_SASIOSAE))
                return 0;

            sbyte[] priority = new sbyte[BSP_TRAINER_DATA.USE_ITEM_MAX];
            for (int i = 0; i < BSP_TRAINER_DATA.USE_ITEM_MAX; i++)
                priority[i] = -1;

            sbyte maxPriority = -1;
            for (int i = 0; i < BSP_TRAINER_DATA.USE_ITEM_MAX; i++)
            {
                if (useItemMemberCount[i] < aliveMemberCount)
                    break;

                if (m_AIItem[i] == 0)
                    continue;

                if (calc.ITEM_IsBall(m_AIItem[i]))
                {
                    priority[i] = 0;
                }
                else if (calc.ITEM_GetParam(m_AIItem[i], Pml.Item.ItemData.PrmID.HP_RCV) != 0)
                {
                    if ((uint)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_HP) <= calc.QuotMaxHP_Zero(bpp, 4, false))
                        priority[i] = (sbyte)tables.GetAIItemPriority(m_AIItem[i]);
                }
                else if (check_status_up_item(m_AIItem[i], bpp) || check_cure_sick_item(m_AIItem[i], bpp))
                {
                    priority[i] = (sbyte)tables.GetAIItemPriority(m_AIItem[i]);
                }

                if (priority[i] > maxPriority)
                    maxPriority = priority[i];
            }

            if (maxPriority < 0)
                return 0;

            for (int i = 0; i < BSP_TRAINER_DATA.USE_ITEM_MAX; i++)
            {
                if (priority[i] == maxPriority)
                {
                    ushort itemID = m_AIItem[i];
                    m_AIItem[i] = 0;
                    return itemID;
                }
            }

            return 0;
        }
		private bool check_status_up_item(ushort itemID, global::Dpr.Battle.Logic.BTL_POKEPARAM bpp) {
            for (int i = 0; i < check_status_up_item_check_tbl.Length; i++)
            {
                if (calc.ITEM_GetParam(itemID, check_status_up_item_check_tbl[i].itemParamID) != 0 &&
                    bpp.IsRankEffectValid(check_status_up_item_check_tbl[i].rankID, 1))
                    return true;
            }

            if (calc.ITEM_GetParam(itemID, Pml.Item.ItemData.PrmID.CRITICAL_UP) != 0 && bpp.GetCriticalRank() == 0)
                return true;

            return calc.ITEM_GetParam(itemID, Pml.Item.ItemData.PrmID.ABILITY_GUARD) != 0;
        }
		private bool check_cure_sick_item(ushort itemID, global::Dpr.Battle.Logic.BTL_POKEPARAM bpp) {
            for (int i = 0; i < check_cure_sick_item_check_tbl.Length; i++)
            {
                if (calc.ITEM_GetParam(itemID, check_cure_sick_item_check_tbl[i].itemParamID) != 0 &&
                    bpp.CheckSick(check_cure_sick_item_check_tbl[i].sickID))
                    return true;
            }

            return false;
        }
