		private bool SubProc_UI_Setup(ref int seq) {
            switch (seq)
            {
                case 0:
                    m_viewCore.CMD_StartSetup();
                    seq++;
                    goto case 1;

                case 1:
                    if (!m_viewCore.CMD_WaitSetup())
                        return false;

                    m_frEffectProc.Start(m_mainModule, getPokeCon(), m_viewCore, m_myID, getMyCoverPosNum());
                    seq = 2;
                    goto case 2;

                case 2:
                    if (!m_frEffectProc.Wait())
                        return false;

                    seq = 4;
                    goto case 4;

                case 4:
                    if (m_cmdLimitTime != 0 || m_gameLimitTime != 0 || m_clientLimitTime != 0)
                    {
                        m_gameTimer.SetTime(GameTimer.TimerType.GAME, m_gameLimitTime);
                        m_gameTimer.SetTime(GameTimer.TimerType.CLIENT, m_clientLimitTime);
                        m_gameTimer.SetTime(GameTimer.TimerType.COMMAND, m_cmdLimitTime);
                        if (m_gameLimitTime != 0)
                            m_viewCore_CMD_EFFECT_DrawEnableTimer(GameTimer.TimerType.GAME, true);

                        if (m_clientLimitTime != 0)
                            m_viewCore_CMD_EFFECT_DrawEnableTimer(GameTimer.TimerType.CLIENT, true);
                    }

                    enemyPokeHPBase_Update();

                    if (IsChapterSkipMode())
                        m_viewCore.CMD_RecPlayer_StartSkip();

                    return true;

                default:
                    return false;
            }
        }
		private bool SubProc_AI_Setup(ref int seq) {
            m_cmdLimitTime = (ushort)m_mainModule.GetCommandLimitTime();
            m_gameLimitTime = (ushort)m_mainModule.GetGameLimitTime();
            m_clientLimitTime = (ushort)m_mainModule.GetClientLimitTime();
            return true;
        }
		private bool SubProc_REC_Setup(ref int seq) {
            if (m_mainModule.IsWatchMember())
            {
                if (m_mainModule.GetBattleSetupParam().recRandSeed == 0)
                    return false;

                if (!m_isLiveRecSeedSetup)
                {
                    m_isLiveRecSeedSetup = true;
                    calc.ResetSys(m_mainModule.GetBattleSetupParam().recRandSeed);
                }
            }

            if (m_viewCore == null)
            {
                m_btlRecReader.CheckBtlInCmd(m_myID);
                return true;
            }

            if (!SubProc_UI_Setup(ref seq))
                return false;

            if (m_btlRecReader.CheckBtlInCmd(m_myID))
                RecPlayer_TurnIncReq(m_recPlayer);

            return true;
        }
		private void enemyPokeHPBase_Update() {
            BTL_POKEPARAM targetPoke = enemyPokeHPBase_GetTargetPoke();
            if (targetPoke != null)
                m_EnemyPokeHPBase = (ushort)targetPoke.GetValue(BTL_POKEPARAM.ValueID.BPP_HP);
        }
		private uint enemyPokeHPBase_CheckRatio() {
            BTL_POKEPARAM targetPoke = enemyPokeHPBase_GetTargetPoke();
            if (targetPoke == null)
                return 0;

            uint hp = (uint)targetPoke.GetValue(BTL_POKEPARAM.ValueID.BPP_HP);
            if (hp == 0)
                return 0;

            if (hp >= m_EnemyPokeHPBase)
                return 0;

            return (m_EnemyPokeHPBase - hp) * 100 / hp;
        }
		private global::Dpr.Battle.Logic.BTL_POKEPARAM enemyPokeHPBase_GetTargetPoke() {
            if (m_mainModule.GetCommMode() != BtlCommMode.BTL_COMM_NONE)
                return null;

            if (m_mainModule.GetRule() != BtlRule.BTL_RULE_SINGLE)
                return null;

            byte opponentClientID = (byte)m_mainModule.GetOpponentClientID(m_myID, 0);
            return getPokeCon().GetClientPokeDataConst(opponentClientID, 0);
        }
		private void startGameTimeCountDown() {
            m_gameTimer.StartCountDown(GameTimer.TimerType.GAME, TimerControlLevel.CLIENT);
        }
		private void cmdLimit_Start() {
            if (m_cmdLimitTime != 0)
            {
                uint cmdLimitTime = m_cmdLimitTime;
                if (IsCheerMode())
                    cmdLimitTime /= 2;

                m_gameTimer.SetTime(GameTimer.TimerType.COMMAND, cmdLimitTime);
                m_gameTimer.StartCountDown(GameTimer.TimerType.COMMAND, TimerControlLevel.CLIENT);
                m_viewCore_CMD_EFFECT_DrawEnableTimer(GameTimer.TimerType.COMMAND, true);
                m_fForceQuitSelAct = false;
            }

            if (m_clientLimitTime != 0)
            {
                unsafe
                {
                    m_gameTimer.SetTime(GameTimer.TimerType.CLIENT, m_syncClientTime.limitTime[m_myID]);
                }
                m_gameTimer.StartCountDown(GameTimer.TimerType.CLIENT, TimerControlLevel.CLIENT);
                m_viewCore_CMD_EFFECT_DrawEnableTimer(GameTimer.TimerType.CLIENT, true);
            }
        }
		private bool cmdLimit_CheckOver() {
            if (m_cmdLimitTime == 0)
                return false;

            if (m_fForceQuitSelAct)
                return true;

            if (m_gameTimer.IsFinish(GameTimer.TimerType.COMMAND))
                m_fForceQuitSelAct = true;

            return m_fForceQuitSelAct;
        }
		private bool checkSelactForceQuit(global::Dpr.Battle.Logic.BTL_CLIENT.ClientSubProc nextProc) {
            if (cmdLimit_CheckOver() || cmdComm_checkError())
            {
                if (nextProc != null)
                    selActSubProc_Set(nextProc);

                return true;
            }

            return false;
        }
		private void cmdLimit_End() {
            if (m_cmdLimitTime != 0)
            {
                m_gameTimer.Pause(GameTimer.TimerType.COMMAND, TimerControlLevel.CLIENT);
                m_viewCore_CMD_EFFECT_DrawEnableTimer(GameTimer.TimerType.COMMAND, false);
            }

            if (m_clientLimitTime != 0)
            {
                m_gameTimer.Pause(GameTimer.TimerType.CLIENT, TimerControlLevel.CLIENT);
                m_viewCore_CMD_EFFECT_DrawEnableTimer(GameTimer.TimerType.CLIENT, false);
            }
        }
		private bool cmdComm_checkError() {
            return m_fCommError;
        }
		private bool setupSelectStartStr(global::Dpr.Battle.Logic.BTL_POKEPARAM procPoke, global::Dpr.Battle.Logic.BTLV_STRPARAM strParam) {
            if (m_mainModule.GetRule() == BtlRule.BTL_RULE_SAFARI)
                return false;

            if (!m_b1stReadyMsgDisped)
            {
                int strID = Kawaigari.Check1stReadyMessage(m_mainModule, procPoke, m_random);
                if (strID >= 0)
                {
                    BTLV_STRPARAM.Setup(strParam, BtlStrType.BTL_STRTYPE_STD, (ushort)strID);
                    BTLV_STRPARAM.AddArg(strParam, procPoke.GetID());
                    BTLV_STRPARAM.AddArg(strParam, m_myID);
                    BTLV_STRPARAM.SetWait(strParam, 12);
                    return true;
                }
            }

            if (m_mainModule.GetPokeFriendship(procPoke) < 220)
            {
                BTLV_STRPARAM.Setup(strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.SelectAction);
                BTLV_STRPARAM.AddArg(strParam, procPoke.GetID());
                BTLV_STRPARAM.SetWait(strParam, 12);
                return false;
            }

            BTLV_STRPARAM.Setup(strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.SelectFriendship);
            BTLV_STRPARAM.AddArg(strParam, procPoke.GetID());
            BTLV_STRPARAM.AddArg(strParam, m_myID);
            BTLV_STRPARAM.SetWait(strParam, 12);
            return true;
        }
		private bool checkFriendshipSpecialMessage(global::Dpr.Battle.Logic.BTL_POKEPARAM procPoke, global::Dpr.Battle.Logic.BTLV_STRPARAM strParam) {
            return false;
        }
		private void selActSubProc_Set(global::Dpr.Battle.Logic.BTL_CLIENT.ClientSubProc proc) {
            m_selActProc = proc;
            m_selActSeq = 0;
        }
		private bool selActSubProc_Call() {
            return m_selActProc(ref m_selActSeq);
        }
		private bool SubProc_UI_SelectAction(ref int seq) {
            switch ((SeqSubProc_UI_SelectAction)seq)
            {
                case SeqSubProc_UI_SelectAction.SEQ_START_0:
                    if (m_mainModule.GetCompetitor(false) == BtlCompetitor.BTL_COMPETITOR_DEMO_CAPTURE && GetTurnCount() == 1)
                    {
                        m_viewCore.CMD_DemoCapture_Start();
                        seq = (int)SeqSubProc_UI_SelectAction.SEQ_DEMOCAPTURE_WAIT;
                        goto case SeqSubProc_UI_SelectAction.SEQ_DEMOCAPTURE_WAIT;
                    }

                    seq = (int)SeqSubProc_UI_SelectAction.SEQ_TRAINER_MESSAGE_SWITCH;
                    goto case SeqSubProc_UI_SelectAction.SEQ_TRAINER_MESSAGE_SWITCH;

                case SeqSubProc_UI_SelectAction.SEQ_DEMOCAPTURE_WAIT:
                    if (!m_viewCore.CMD_DemoCapture_Wait())
                        return false;

                    seq = (int)SeqSubProc_UI_SelectAction.SEQ_TRAINER_MESSAGE_SWITCH;
                    goto case SeqSubProc_UI_SelectAction.SEQ_TRAINER_MESSAGE_SWITCH;

                case SeqSubProc_UI_SelectAction.SEQ_TRAINER_MESSAGE_SWITCH:
                    if (DecideTrainerMessage_OnSelectAction(ref SubProc_UI_SelectAction_trainerMessage_clientID, ref SubProc_UI_SelectAction_trainerMessage_messageID))
                    {
                        seq = (int)SeqSubProc_UI_SelectAction.SEQ_TRAINER_MESSAGE_START;
                        goto case SeqSubProc_UI_SelectAction.SEQ_TRAINER_MESSAGE_START;
                    }

                    seq = (int)SeqSubProc_UI_SelectAction.SEQ_START_1;
                    goto case SeqSubProc_UI_SelectAction.SEQ_START_1;

                case SeqSubProc_UI_SelectAction.SEQ_TRAINER_MESSAGE_START:
                    StartTrainerMessage((byte)SubProc_UI_SelectAction_trainerMessage_clientID, SubProc_UI_SelectAction_trainerMessage_messageID);
                    seq = (int)SeqSubProc_UI_SelectAction.SEQ_TRAINER_MESSAGE_WAIT;
                    goto case SeqSubProc_UI_SelectAction.SEQ_TRAINER_MESSAGE_WAIT;

                case SeqSubProc_UI_SelectAction.SEQ_TRAINER_MESSAGE_WAIT:
                    if (!UpdateTrainerMessage())
                        return false;

                    seq = (int)SeqSubProc_UI_SelectAction.SEQ_START_1;
                    goto case SeqSubProc_UI_SelectAction.SEQ_START_1;

                case SeqSubProc_UI_SelectAction.SEQ_START_1:
                    if (!m_isFirstActionSelectDone)
                    {
                        m_isFirstActionSelectDone = true;
                        onFirstActionSelectStart();
                    }

                    clearSelectedRaidActionIconID();
                    seq = (int)SeqSubProc_UI_SelectAction.SEQ_CAMERA_INIT;
                    goto case SeqSubProc_UI_SelectAction.SEQ_CAMERA_INIT;

                case SeqSubProc_UI_SelectAction.SEQ_CAMERA_INIT:
                    if (!m_viewCore.CMD_InitStartWaitCameraEffect())
                        return false;

                    seq = (int)SeqSubProc_UI_SelectAction.SEQ_CAMERA_WAIT;
                    goto case SeqSubProc_UI_SelectAction.SEQ_CAMERA_WAIT;

                case SeqSubProc_UI_SelectAction.SEQ_CAMERA_WAIT:
                    if (!m_viewCore.CMD_WaitStartWaitCameraEffect())
                        return false;

                    seq = (int)SeqSubProc_UI_SelectAction.SEQ_SELACT_START;
                    goto case SeqSubProc_UI_SelectAction.SEQ_SELACT_START;

                case SeqSubProc_UI_SelectAction.SEQ_SELACT_START:
                    selActSubProc_Set(selact_Start);
                    startGameTimeCountDown();
                    if (!IsGameTimeOver())
                        cmdLimit_Start();

                    seq = (int)SeqSubProc_UI_SelectAction.SEQ_SELACT_WAIT;
                    goto case SeqSubProc_UI_SelectAction.SEQ_SELACT_WAIT;

                case SeqSubProc_UI_SelectAction.SEQ_SELACT_WAIT:
                    cmdLimit_CheckOver();
                    return selActSubProc_Call();

                default:
                    return false;
            }
        }
		private void onFirstActionSelectStart() {
            m_viewCore.CMD_UI_OnFirstSelectActionStart();
        }
		private bool needDisplayTipsForG() {
            if (m_mainModule.GetRule() == BtlRule.BTL_RULE_RAID)
                return false;

            if (m_mainModule.GetCommMode() != BtlCommMode.BTL_COMM_NONE)
                return false;

            return GMode.CanStartG(m_mainModule, m_pBattleEnv, (BTL_CLIENT_ID)m_myID);
        }
		private bool isRandomWaitCameraEnable() {
            return true;
        }
		private bool DecideTrainerMessage_OnSelectAction(ref sbyte clientID, ref global::Dpr.Battle.Logic.TrainerMessageID messageID) {
            if (!m_mainModule.IsCompetitorScenarioMode())
                return false;

            clientID = DecideTrainerMessage_OnSelectAction_FirstDamage();
            if (clientID != -1)
            {
                messageID = TrainerMessageID.MESSAGE_FIRST_DAMAGE;
                return true;
            }

            clientID = DecideTrainerMessage_OnSelectAction_LastPokeHpHalf();
            if (clientID != -1)
            {
                messageID = TrainerMessageID.MESSAGE_LAST_POKE_HP_HALF;
                return true;
            }

            return false;
        }
		private sbyte DecideTrainerMessage_OnSelectAction_FirstDamage() {
            for (byte clientID = 1; clientID <= 4; clientID++)
            {
                if (IsTrainerMessageEnable_OnSelectAction_FirstDamage(clientID))
                    return (sbyte)clientID;
            }

            return -1;
        }
		private bool IsTrainerMessageEnable_OnSelectAction_FirstDamage(byte clientID) {
            if (!m_mainModule.IsClientTrainerExist(clientID))
                return false;

            BTL_PARTY party = getPokeCon().GetPartyDataConst(clientID);
            for (byte i = 0; i < party.GetMemberCount(); i++)
            {
                BTL_POKEPARAM bpp = party.GetMemberData(i);
                if (bpp.IsDead() || bpp.GetHPRatio() < (100 << 12))
                    return m_trainerMessageManager.IsMessageExist(clientID, TrainerMessageID.MESSAGE_FIRST_DAMAGE);
            }

            return false;
        }
		private sbyte DecideTrainerMessage_OnSelectAction_LastPokeHpHalf() {
            for (byte clientID = 1; clientID <= 4; clientID++)
            {
                if (IsTrainerMessageEnable_OnSelectAction_LastPokeHpHalf(clientID))
                    return (sbyte)clientID;
            }

            return -1;
        }
		private bool IsTrainerMessageEnable_OnSelectAction_LastPokeHpHalf(byte clientID) {
            if (!m_mainModule.IsClientTrainerExist(clientID))
                return false;

            BTL_PARTY party = getPokeCon().GetPartyDataConst(clientID);
            if (party.GetAliveMemberCount() != 1)
                return false;

            BTL_POKEPARAM bpp = party.GetMemberDataConst(0);
            if (bpp.IsDead() || bpp.GetHPRatio() > (50 << 12))
                return false;

            return m_trainerMessageManager.IsMessageExist(clientID, TrainerMessageID.MESSAGE_LAST_POKE_HP_HALF);
        }
		private bool SubProc_REC_SelectAction(ref int seq) {
            byte numAction = 0;
            bool fChapter = false;
            bool isBtlInCmd = false;

            if (m_mainModule.IsWatchMember() && m_viewCore != null)
            {
                switch (m_liveRecWaitCameraSeq)
                {
                    case 2:
                        if (m_viewCore.CMD_WaitStartWaitCameraEffect())
                        {
                            m_liveRecWaitCameraSeq = 3;
                            return false;
                        }
                        break;

                    case 3:
                        if (m_liveRecSizeSave != m_mainModule.GetBattleSetupParam().recDataSize || m_fCommError)
                        {
                            m_viewCore.CMD_InitFinishWaitCameraEffect();
                            m_liveRecWaitCameraSeq = 4;
                            return false;
                        }
                        break;

                    case 4:
                        if (m_viewCore.CMD_WaitFinishWaitCameraEffect())
                            m_liveRecWaitCameraSeq = 1;
                        break;
                }

                if (m_liveRecWaitCameraSeq > 1)
                    return false;
            }

            switch ((SeqSubProc_REC_SelectAction)seq)
            {
                case SeqSubProc_REC_SelectAction.SEQ_FIRST:
                {
                    if (m_fRecPlayEndBufOver || m_bRecPlayFadeStarted)
                    {
                        setNullActionRecplay();
                        return true;
                    }

                    if (m_mainModule.IsWatchMember())
                    {
                        if (m_fCommError)
                            return true;

                        startGameTimeCountDown();
                        m_btlRecReader.ResetError();
                        m_btlRecReader.SetDataSize(m_mainModule.GetBattleSetupParam().recDataSize);
                        if (m_btlRecReader.IsReadComplete(m_myID))
                        {
                            if (m_liveRecWaitCameraSeq != 0)
                            {
                                m_liveRecWaitCameraSeq = 2;
                                if (m_viewCore != null)
                                    m_viewCore.CMD_InitStartWaitCameraEffect();
                            }

                            m_liveRecSizeSave = m_mainModule.GetBattleSetupParam().recDataSize;
                            return false;
                        }
                    }

                    isBtlInCmd = false;
                    unsafe
                    {
                        BTL_ACTION_PARAM* actionParam = m_btlRecReader.ReadAction(m_myID, out numAction, out fChapter, out isBtlInCmd);
                        if (isBtlInCmd && m_liveRecWaitCameraSeq == 0)
                            m_liveRecWaitCameraSeq = 1;

                        if (fChapter)
                            RecPlayer_TurnIncReq(m_recPlayer);

                        storeActionSelectSendData(actionParam, numAction);

                        switch (BTL_ACTION.GetAction(actionParam[0]))
                        {
                            case BtlAction.BTL_ACTION_RECPLAY_ERROR:
                                if (m_mainModule.IsWatchMember())
                                    return false;

                                m_fRecPlayEndBufOver = true;
                                RecPlayer_Quit(m_recPlayer);
                                if (m_viewCore == null)
                                {
                                    setNullActionRecplay();
                                    return true;
                                }

                                BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.BatteRecBufferOver);
                                m_viewCore.CMD_StartMsg(m_strParam);
                                seq += 2;
                                return false;

                            case BtlAction.BTL_ACTION_RECPLAY_TIMEOVER:
                                RecPlayer_Quit(m_recPlayer);
                                if (m_viewCore == null)
                                {
                                    setNullActionRecplay();
                                    m_fRecPlayEndTimeOver = true;
                                    return true;
                                }

                                BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.BattleTimeOver);
                                m_viewCore.CMD_StartMsg(m_strParam);
                                seq++;
                                return false;

                            default:
                                return true;
                        }
                    }
                }

                case SeqSubProc_REC_SelectAction.SEQ_NONE:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    setNullActionRecplay();
                    m_fRecPlayEndTimeOver = true;
                    return true;

                case SeqSubProc_REC_SelectAction.SEQ_START_WAIT:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    setNullActionRecplay();
                    return true;

                default:
                    return false;
            }
        }
		private void setNullActionRecplay() {
            m_procActionIndex = 0;
            BTL_ACTION.SetNULL(ref m_actionParam[0]);
            storeActionSelectSendData(m_actionParam, 1);
        }
		private bool selact_Start(ref int seq) {
            BTL_ACTION_PARAM action = default;

            m_procPokeIdx = 0;
            m_prevPokeIdx = -1;
            m_firstPokeIdx = 0;
            m_wazaInfoPokeIdx = 0;
            m_fSelActForceFinish = false;

            byte numCoverPos = getMyCoverPosNum();
            setupPokeSelParam(numCoverPos, m_pokeSelParam, m_pokeSelResult);
            selItemWork_Init();
            selact_ClearWorks();

            action = default;
            for (byte i = 0; i < numCoverPos; i++)
            {
                BTL_POKEPARAM bpp = getPokeCon().GetClientPokeData(m_myID, i);
                if (!checkActionForceSet(bpp, ref action))
                {
                    m_firstPokeIdx = i;
                    break;
                }
            }

            if (IsGameTimeOver())
            {
                for (; m_procPokeIdx < numCoverPos; m_procPokeIdx++)
                {
                    setupCurrentPokeActionPtr();
                    setActionForce(ref m_actionParam[m_procActionIndex], m_procPoke);
                }

                setupSelActReturnData();
                selActSubProc_Set(selact_Finish);
            }
            else
            {
                selActSubProc_Set(selact_Root);
            }

            return false;
        }
		private void selact_startMsg(global::Dpr.Battle.Logic.BTLV_STRPARAM strParam) {
            m_viewCore.CMD_StartMsg(strParam);
            m_fStdMsgChanged = true;
        }
		private void selact_ClearWorks() {
            for (int i = 0; i < m_actionParam.Length; i++)
                BTL_ACTION.SetNULL(ref m_actionParam[i]);

            for (int i = 0; i < m_actionCountWork.Length; i++)
                m_actionCountWork[i] = 0;

            m_isGSelectedThisTurn = false;
        }
		private bool selact_ForceQuit(ref int seq) {
            switch (seq)
            {
                case 0:
                    m_viewCore.CMD_ForceQuitInput_Notify();
                    seq++;
                    break;

                case 1:
                {
                    if (!m_viewCore.CMD_ForceQuitInput_Wait())
                        return false;

                    byte numCoverPos = getMyCoverPosNum();
                    for (; m_procPokeIdx < numCoverPos; m_procPokeIdx++)
                    {
                        setupCurrentPokeActionPtr();
                        setActionForce(ref m_actionParam[m_procActionIndex], m_procPoke);
                    }

                    seq++;
                    break;
                }

                case 2:
                    setupSelActReturnData();
                    selActSubProc_Set(selact_Finish);
                    break;
            }

            return false;
        }
		private void setActionForce(ref global::Dpr.Battle.Logic.BTL_ACTION_PARAM pActionParam, global::Dpr.Battle.Logic.BTL_POKEPARAM poke) {
            if (IsCheerMode())
            {
                BTL_ACTION.SetCheer(ref pActionParam);
                return;
            }

            if (checkActionForceSet(poke, ref pActionParam))
                return;

            bool[] selectableFlags = new bool[BattleDefConst.PTL_WAZA_MAX];
            byte wazaIdx = storeSelectableWazaFlag(poke, poke.IsGMode(), selectableFlags);
            if (wazaIdx == BattleDefConst.PTL_WAZA_MAX)
            {
                setWaruagakiAction(ref pActionParam, poke);
                return;
            }

            WazaNo srcWaza = poke.WAZA_GetID(wazaIdx);
            WazaNo waza = srcWaza;
            if (poke.IsGMode())
                waza = GWaza.GetGWaza(srcWaza);

            BtlPokePos targetPos = calc.DecideWazaTargetAutoForClient(m_mainModule, getPokeCon(), poke, waza, ref m_randContext);
            BTL_ACTION.SetFightParam(ref pActionParam, poke.GetID(), srcWaza, targetPos);
        }
		private bool selact_Root(ref int seq) {
            BattleViewBase.SelectActionParam viewParam = null;

            switch ((SelActRootSeq)seq)
            {
                case SelActRootSeq.SELACT_ROOTSEQ_START:
                    selact_root_start(ref seq);
                    if (seq != (int)SelActRootSeq.SELACT_ROOTSEQ_WAIT_MSG_CHECK)
                        return false;

                    goto case SelActRootSeq.SELACT_ROOTSEQ_WAIT_MSG_CHECK;

                case SelActRootSeq.SELACT_ROOTSEQ_FRIENDSHIP_MSG_WAIT:
                case SelActRootSeq.SELACT_ROOTSEQ_FREEFALL_WARN_WAIT:
                    selact_root_friendship_msg_wait(ref seq);
                    return false;

                case SelActRootSeq.SELACT_ROOTSEQ_WAIT_MSG_CHECK:
                    selact_root_wait_msg_check(ref seq);
                    if (seq == (int)SelActRootSeq.SELACT_ROOTSEQ_SEL_START)
                        goto case SelActRootSeq.SELACT_ROOTSEQ_SEL_START;

                    goto case SelActRootSeq.SELACT_ROOTSEQ_WAIT_MSG_WAIT;

                case SelActRootSeq.SELACT_ROOTSEQ_WAIT_MSG_WAIT:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    seq = (int)SelActRootSeq.SELACT_ROOTSEQ_SEL_START;
                    goto case SelActRootSeq.SELACT_ROOTSEQ_SEL_START;

                case SelActRootSeq.SELACT_ROOTSEQ_SEL_START:
                    viewParam = new BattleViewBase.SelectActionParam();
                    setupSelectActionUIParam(viewParam, m_procPoke, m_procPokeIdx);
                    m_procActionUIRet.value = m_procAction;
                    m_viewCore.CMD_UI_SelectAction_Start(viewParam, m_procActionUIRet);
                    seq = (int)SelActRootSeq.SELACT_ROOTSEQ_SEL_MAIN;
                    return false;

                case SelActRootSeq.SELACT_ROOTSEQ_SEL_MAIN:
                    selact_root_sel_main(ref seq);
                    m_procAction = m_procActionUIRet.value;
                    return false;

                case SelActRootSeq.SELACT_ROOTSEQ_WAIT_UI_RESTART:
                    if (m_viewCore.CMD_UI_WaitRestart())
                        seq = (int)SelActRootSeq.SELACT_ROOTSEQ_SEL_START;
                    return false;

                case SelActRootSeq.SELACT_ROOTSEQ_FREEFALL_WARN:
                    m_viewCore.CMD_UI_RestartIfNotStandBy();
                    seq = (int)SelActRootSeq.SELACT_ROOTSEQ_FREEFALL_WARN_MSG;
                    return false;

                case SelActRootSeq.SELACT_ROOTSEQ_FREEFALL_WARN_MSG:
                    if (!m_viewCore.CMD_UI_WaitRestart())
                        return false;

                    BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.FreeFallBind);
                    BTLV_STRPARAM.AddArg(m_strParam, m_procPoke.GetID());
                    selact_startMsg(m_strParam);
                    seq = (int)SelActRootSeq.SELACT_ROOTSEQ_FREEFALL_WARN_WAIT;
                    return false;

                default:
                    return false;
            }
        }
		private void setupSelectActionUIParam(global::Dpr.Battle.Logic.BattleViewBase.SelectActionParam pViewParam, global::Dpr.Battle.Logic.BTL_POKEPARAM pActPoke, byte actPokeIdx) {
            pViewParam.pActPoke = pActPoke;
            pViewParam.pokeIndex = actPokeIdx;
            pViewParam.fReturnable = m_firstPokeIdx < actPokeIdx;
            pViewParam.bGEnable = canStartG(pActPoke);
            pViewParam.buttonMode_Cheer = BattleViewBase.ButtonMode.INVISIBLE;
            pViewParam.isBallShortcutEnable = true;
            pViewParam.isInfoEnable = true;
            pViewParam.buttonMode_Fight = BattleViewBase.ButtonMode.ACTIVE;
            pViewParam.buttonMode_Bag = BattleViewBase.ButtonMode.ACTIVE;
            pViewParam.buttonMode_Pokemon = BattleViewBase.ButtonMode.ACTIVE;
            pViewParam.buttonMode_Escape = BattleViewBase.ButtonMode.ACTIVE;

            if (!ItemData.IsBallExist() || m_mainModule.GetCompetitor(true) == BtlCompetitor.BTL_COMPETITOR_TRAINER)
                pViewParam.isBallShortcutEnable = false;

            if (m_mainModule.GetRule() == BtlRule.BTL_RULE_RAID)
            {
                if (m_myParty.GetAliveMemberCount() == 0)
                {
                    pViewParam.buttonMode_Fight = BattleViewBase.ButtonMode.INVISIBLE;
                    pViewParam.buttonMode_Bag = BattleViewBase.ButtonMode.INVISIBLE;
                    pViewParam.buttonMode_Cheer = BattleViewBase.ButtonMode.ACTIVE;
                }

                pViewParam.isBallShortcutEnable = false;
                return;
            }

            if (m_viewCore.IsTutorial())
            {
                pViewParam.buttonMode_Bag = BattleViewBase.ButtonMode.INVISIBLE;
                pViewParam.buttonMode_Pokemon = BattleViewBase.ButtonMode.INVISIBLE;
                pViewParam.buttonMode_Escape = BattleViewBase.ButtonMode.INVISIBLE;
                return;
            }

            BtlCompetitor competitor = m_mainModule.GetCompetitor(true);
            if (competitor == BtlCompetitor.BTL_COMPETITOR_INST || competitor == BtlCompetitor.BTL_COMPETITOR_COMM)
            {
                pViewParam.buttonMode_Bag = BattleViewBase.ButtonMode.INVISIBLE;
                pViewParam.isBallShortcutEnable = false;
            }
        }
		private byte calcAddActionCountSum(byte pokeIdx) {
            byte sum = 0;
            for (int i = 0; i <= pokeIdx; i++)
                sum += m_actionCountWork[i];

            return sum;
        }
		private void setupCurrentPokeActionPtr() {
            byte addActionCountSum = calcAddActionCountSum(m_procPokeIdx);
            m_procPoke = getPokeCon().GetClientPokeData(m_myID, m_procPokeIdx);
            m_procActionIndex = m_procPokeIdx + addActionCountSum;
            m_currentActionIndex = m_procPokeIdx;
            m_currentActionCount = 0;
            BTL_ACTION.SetNULL(ref m_actionParam[m_procActionIndex]);
        }
		private bool selact_root_start(ref int seq) {
            setupCurrentPokeActionPtr();
            if (checkActionForceSet(m_procPoke, ref m_actionParam[m_procActionIndex]))
                selActSubProc_Set(selact_CheckFinish);
            else
                seq = (int)SelActRootSeq.SELACT_ROOTSEQ_WAIT_MSG_CHECK;

            return false;
        }
		private void incrementAddActionCount() {
            m_currentActionCount++;
        }
		private void decrementAddActionCount() {
            if (m_currentActionCount != 0)
                m_currentActionCount--;
        }
		private bool selact_root_friendship_msg_wait(ref int seq) {
            if (m_viewCore.CMD_WaitMsg())
                seq = (int)SelActRootSeq.SELACT_ROOTSEQ_WAIT_MSG_CHECK;

            return false;
        }
		private bool selact_root_wait_msg_check(ref int seq) {
            if (m_prevPokeIdx != m_procPokeIdx || m_fStdMsgChanged)
            {
                if (setupSelectStartStr(m_procPoke, m_strParam))
                {
                    m_viewCore.CMD_StartMsg(m_strParam);
                    m_fStdMsgChanged = false;
                    m_b1stReadyMsgDisped = true;
                }

                m_prevPokeIdx = (sbyte)m_procPokeIdx;
                seq = (int)SelActRootSeq.SELACT_ROOTSEQ_WAIT_MSG_WAIT;
            }
            else
            {
                seq = (int)SelActRootSeq.SELACT_ROOTSEQ_SEL_START;
            }

            return false;
        }
		private bool selact_root_sel_main(ref int seq) {
            if (checkSelactForceQuit(selact_ForceQuit))
            {
                m_viewCore.CMD_UI_SelectAction_ForceQuit();
                return false;
            }

            BtlAction action = m_viewCore.CMD_UI_SelectAction_Wait();
            if (m_mainModule.GetRule() == BtlRule.BTL_RULE_SAFARI)
            {
                switch (action)
                {
                    case BtlAction.BTL_ACTION_FIGHT:
                    case BtlAction.BTL_ACTION_SAFARI_BALL:
                        return selectSafariBall(ref seq);

                    case BtlAction.BTL_ACTION_ITEM:
                    case BtlAction.BTL_ACTION_SAFARI_DORO:
                        BTL_ACTION.SetSafariDoro(ref m_procActionUIRet.value, m_procPoke.GetID());
                        selActSubProc_Set(selact_CheckFinish);
                        return false;

                    case BtlAction.BTL_ACTION_CHANGE:
                    case BtlAction.BTL_ACTION_SAFARI_ESA:
                        BTL_ACTION.SetSafariEsa(ref m_procActionUIRet.value, m_procPoke.GetID());
                        selActSubProc_Set(selact_CheckFinish);
                        return false;

                    case BtlAction.BTL_ACTION_ESCAPE:
                        return selectEscape(ref seq);

                    case BtlAction.BTL_ACTION_CHEER:
                        BTL_ACTION.SetCheer(ref m_procActionUIRet.value);
                        selActSubProc_Set(selact_CheckFinish);
                        return false;

                    default:
                        return false;
                }
            }

            switch (action)
            {
                case BtlAction.BTL_ACTION_FIGHT:
                    selActSubProc_Set(selact_Fight);
                    return false;

                case BtlAction.BTL_ACTION_ITEM:
                    if (m_procPoke.CheckSick(WazaSick.WAZASICK_FREEFALL))
                        return restartForFreeFall(ref seq);

                    selActSubProc_Set(selact_Item);
                    return false;

                case BtlAction.BTL_ACTION_CHANGE:
                    if (m_procPoke.CheckSick(WazaSick.WAZASICK_FREEFALL))
                        return restartForFreeFall(ref seq);

                    selActSubProc_Set(selact_SelectChangePokemon);
                    return false;

                case BtlAction.BTL_ACTION_ESCAPE:
                    return selectEscape(ref seq);

                case BtlAction.BTL_ACTION_CHEER:
                    BTL_ACTION.SetCheer(ref m_procActionUIRet.value);
                    selActSubProc_Set(selact_CheckFinish);
                    return false;

                case BtlAction.BTL_ACTION_SAFARI_BALL:
                    return selectSafariBall(ref seq);

                case BtlAction.BTL_ACTION_SAFARI_ESA:
                    BTL_ACTION.SetSafariEsa(ref m_procActionUIRet.value, m_procPoke.GetID());
                    selActSubProc_Set(selact_CheckFinish);
                    return false;

                case BtlAction.BTL_ACTION_SAFARI_DORO:
                    BTL_ACTION.SetSafariDoro(ref m_procActionUIRet.value, m_procPoke.GetID());
                    selActSubProc_Set(selact_CheckFinish);
                    return false;

                default:
                    return false;
            }

            bool selectSafariBall(ref int s)
            {
                // the shipped code passes the safari ball item number (5); canUseBall ignores it
                if (calc.ITEM_IsBall(5) && !canUseBall(m_strParam, 5, m_procPokeIdx))
                {
                    selActSubProc_Set(selact_Item);
                    s = (int)Seqselact_Item.SEQ_CANT_USE_START;
                    return false;
                }

                BTL_ACTION.SetSafariBall(ref m_procActionUIRet.value, m_procPoke.GetID());
                selActSubProc_Set(selact_CheckFinish);
                return false;
            }

            bool restartForFreeFall(ref int s)
            {
                m_viewCore.CMD_UI_Restart();
                s = (int)SelActRootSeq.SELACT_ROOTSEQ_FREEFALL_WARN;
                return false;
            }

            bool selectEscape(ref int s)
            {
                if (m_procPokeIdx == m_firstPokeIdx)
                {
                    if (m_procPoke.CheckSick(WazaSick.WAZASICK_FREEFALL) && m_mainModule.GetEscapeMode() != BtlEscapeMode.BTL_ESCAPE_MODE_CONFIRM)
                        return restartForFreeFall(ref s);

                    selActSubProc_Set(selact_Escape);
                    return false;
                }

                BTL_ACTION_PARAM tmpAction = default;
                while (true)
                {
                    if (m_procPokeIdx == 0)
                        return false;

                    m_procPokeIdx--;
                    BTL_POKEPARAM bpp = getPokeCon().GetClientPokeData(m_myID, m_procPokeIdx);
                    if (!checkActionForceSet(bpp, ref tmpAction))
                        break;
                }

                ref BTL_ACTION_PARAM prevAction = ref m_actionParam[m_procPokeIdx + calcAddActionCountSum(m_procPokeIdx)];
                if (BTL_ACTION.GetAction(prevAction) == BtlAction.BTL_ACTION_CHANGE)
                    m_pokeSelResult.Pop();

                if (BTL_ACTION.GetAction(prevAction) == BtlAction.BTL_ACTION_ITEM)
                {
                    if (selItemWork_IsFromPokeSelect(m_procPokeIdx))
                        m_pokeSelResult.Pop();

                    selItemWork_Restore(m_procPokeIdx);
                }

                if (BTL_ACTION.IsFightWithG(ref prevAction))
                    m_isGSelectedThisTurn = false;

                selActSubProc_Set(selact_Root);
                return false;
            }
        }
		private bool canStartG(global::Dpr.Battle.Logic.BTL_POKEPARAM pPoke) {
            return GMode.CanStartG(m_mainModule, m_pBattleEnv, (BTL_CLIENT_ID)m_myID) && !m_isGSelectedThisTurn && pPoke.CanStartG();
        }
		private bool selact_Fight(ref int seq) {
            switch ((Seqselact_Fight)seq)
            {
                case Seqselact_Fight.SEQ_START:
                    if (checkWazaForceSet(m_procPoke, ref m_procAction))
                    {
                        selActSubProc_Set(selact_CheckFinish);
                        break;
                    }

                    seq = (int)Seqselact_Fight.SEQ_SELECT_WAZA_START;
                    break;

                case Seqselact_Fight.SEQ_SELECT_WAZA_START:
                    m_procActionUIRet.value = m_procAction;
                    m_viewCore.CMD_UI_SelectWaza_Start(m_procPoke, m_procPokeIdx, m_procActionUIRet);
                    seq = (int)Seqselact_Fight.SEQ_SELECT_WAZA_WAIT;
                    break;

                case Seqselact_Fight.SEQ_SELECT_WAZA_WAIT:
                {
                    if (checkSelactForceQuit(selact_ForceQuit))
                    {
                        m_viewCore.CMD_UI_SelectWaza_ForceQuit();
                        break;
                    }

                    bool fDone = m_viewCore.CMD_UI_SelectWaza_Wait();
                    m_procAction = m_procActionUIRet.value;
                    if (!fDone)
                        return false;

                    if (BTL_ACTION.GetAction(m_procAction) == BtlAction.BTL_ACTION_NULL)
                    {
                        selActSubProc_Set(selact_Root);
                        break;
                    }

                    BTL_POKEPARAM bpp = m_procPoke;
                    WazaNo waza = BTL_ACTION.GetWazaID(ref m_procAction);
                    if (bpp.IsGMode() || BTL_ACTION.IsFightWithG(ref m_procAction))
                        waza = GWaza.GetGWaza(waza);

                    if (is_unselectable_waza(bpp, waza, m_strParam))
                    {
                        BTLV_STRPARAM.SetWait(m_strParam, 0);
                        selact_startMsg(m_strParam);
                        seq = (int)Seqselact_Fight.SEQ_WAIT_UNSEL_WAZA_MSG;
                        break;
                    }

                    seq = (int)Seqselact_Fight.SEQ_SELECT_WAZA_END;
                    break;
                }

                case Seqselact_Fight.SEQ_SELECT_WAZA_END:
                    if (m_viewCore.CMD_UI_SelectWaza_End())
                        seq = (int)Seqselact_Fight.SEQ_CHECK_WAZA_TARGET;
                    break;

                case Seqselact_Fight.SEQ_CHECK_WAZA_TARGET:
                {
                    BtlRule rule = m_mainModule.GetRule();
                    if (calc.RULE_IsNeedSelectTarget(rule))
                    {
                        if (rule == BtlRule.BTL_RULE_RAID && m_mainModule.GetMultiMode() == BtlMultiMode.BTL_MULTIMODE_RAID_P_A &&
                            WAZADATA.GetWazaTarget(BTL_ACTION.GetWazaID(ref m_procAction)) == Pml.WazaData.WazaTarget.TARGET_FRIEND_SELECT)
                        {
                            m_procAction.fight_targetPos = 0;
                            seq = (int)Seqselact_Fight.SEQ_DONE;
                            break;
                        }

                        seq = (int)Seqselact_Fight.SEQ_SELECT_TARGET_START;
                        break;
                    }

                    BtlPokePos myPos = m_mainModule.PokeIDtoPokePos(getPokeCon(), m_procPoke.GetID());
                    m_procAction.fight_targetPos = (byte)m_mainModule.GetOpponentPokePos(myPos, 0);
                    seq = (int)Seqselact_Fight.SEQ_DONE;
                    break;
                }

                case Seqselact_Fight.SEQ_WAIT_UNSEL_TARGET_MSG:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    goto case Seqselact_Fight.SEQ_SELECT_TARGET_START;

                case Seqselact_Fight.SEQ_SELECT_TARGET_START:
                    m_procActionUIRet.value = m_procAction;
                    m_viewCore.CMD_UI_SelectTarget_Start(m_procPokeIdx, m_procPoke, m_procActionUIRet);
                    seq = (int)Seqselact_Fight.SEQ_SELECT_TARGET_WAIT;
                    break;

                case Seqselact_Fight.SEQ_SELECT_TARGET_WAIT:
                {
                    if (checkSelactForceQuit(selact_ForceQuit))
                    {
                        m_viewCore.CMD_UI_SelectTarget_ForceQuit();
                        break;
                    }

                    BattleViewBase.BtlvResult result = m_viewCore.CMD_UI_SelectTarget_Wait();
                    m_procAction = m_procActionUIRet.value;
                    if (result == BattleViewBase.BtlvResult.CANCEL)
                    {
                        seq = (int)Seqselact_Fight.SEQ_SELECT_WAZA_START;
                        break;
                    }

                    if (result != BattleViewBase.BtlvResult.DONE)
                        return false;

                    WazaNo waza = BTL_ACTION.GetWazaID(ref m_procAction);
                    BtlPokePos targetPos = BTL_ACTION.GetWazaTargetPos(ref m_procAction);
                    if (is_unselectable_target(m_procPoke, waza, targetPos, m_strParam))
                    {
                        BTLV_STRPARAM.SetWait(m_strParam, 0);
                        selact_startMsg(m_strParam);
                        seq = (int)Seqselact_Fight.SEQ_WAIT_UNSEL_TARGET_MSG;
                        break;
                    }

                    seq = (int)Seqselact_Fight.SEQ_DONE;
                    break;
                }

                case Seqselact_Fight.SEQ_WAIT_UNSEL_WAZA_MSG:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    m_viewCore.CMD_UI_SelectWaza_Restart(m_procPokeIdx);
                    seq = (int)Seqselact_Fight.SEQ_SELECT_WAZA_WAIT;
                    break;

                case Seqselact_Fight.SEQ_DONE:
                    if (BTL_ACTION.IsFightWithG(ref m_procAction))
                        m_isGSelectedThisTurn = true;

                    selActSubProc_Set(selact_CheckFinish);
                    break;
            }

            return false;
        }
		private bool needGButtonDisplay(global::Dpr.Battle.Logic.BTL_POKEPARAM pActPoke) {
            return GMode.NeedGButtonDisplay(m_mainModule, m_pBattleEnv, (BTL_CLIENT_ID)m_myID) && !m_isGSelectedThisTurn && pActPoke.CanStartG();
        }
		private bool selact_SelectChangePokemon(ref int seq) {
            switch (seq)
            {
                case 0:
                {
                    CantEscapeCode code = isForbidPokeChange(m_procPoke, out byte pokeID, out ushort tokuseiID);
                    bool fCantEsc = !(code == CantEscapeCode.CANTESC_NULL && pokeID != m_procPoke.GetID());
                    if (m_mainModule.GetRule() == BtlRule.BTL_RULE_RAID)
                        fCantEsc |= m_myParty.GetAliveMemberCount() == 0;

                    m_pokeSelResult.SetCancel(false);
                    m_viewCore.CMD_StartPokeList(m_pokeSelParam, m_procPoke, m_procPokeIdx, fCantEsc, m_pokeSelResult);
                    seq++;
                    break;
                }

                case 1:
                    if (checkSelactForceQuit(null))
                    {
                        m_viewCore.CMD_ForceQuitPokeList();
                        seq = 2;
                        break;
                    }

                    if (!m_viewCore.CMD_WaitPokeList())
                        return false;

                    if (m_pokeSelResult.IsCancel())
                    {
                        selActSubProc_Set(selact_Root);
                        break;
                    }

                    if (m_pokeSelResult.IsItemUse(out BTL_CLIENT_ID clientID, out byte pokeIdx, out ushort itemNo, out byte wazaIdx))
                    {
                        byte targetID = getPokeCon().GetPartyDataConst((byte)clientID).GetMemberDataConst(pokeIdx).GetID();
                        BTL_ACTION.SetItemParam(ref m_actionParam[m_procActionIndex], m_procPoke.GetID(), itemNo, targetID, wazaIdx);
                        m_viewCore.CMD_ITEMSELECT_ReflectUsedItem();
                        selItemWork_Reserve(m_procPokeIdx, itemNo, true);
                    }
                    else
                    {
                        byte memberIdx = m_pokeSelResult.GetLast();
                        if (memberIdx >= PokeParty.MAX_MEMBERS)
                        {
                            selActSubProc_Set(selact_Root);
                            break;
                        }

                        BTL_ACTION.SetChangeParam(ref m_actionParam[m_procActionIndex], m_procPokeIdx, memberIdx);
                    }

                    selActSubProc_Set(selact_CheckFinish);
                    break;

                case 2:
                    if (!m_viewCore.CMD_WaitForceQuitPokeList())
                        return false;

                    selActSubProc_Set(selact_ForceQuit);
                    break;
            }

            return false;
        }
		private bool selact_Item(ref int seq) {
            switch ((Seqselact_Item)seq)
            {
                case Seqselact_Item.SEQ_START:
                    if (!canSelectItem(m_strParam))
                        seq = (int)Seqselact_Item.SEQ_CANT_USE_START;
                    else
                        seq = (int)Seqselact_Item.SEQ_SELECT_START;
                    break;

                case Seqselact_Item.SEQ_SELECT_START:
                {
                    bool fFirstPokemon = m_procPokeIdx == m_firstPokeIdx;
                    m_viewCore.CMD_ITEMSELECT_Start(m_bagMode, 0, 0, fFirstPokemon, checkBallTargetHide(), m_mainModule.GetRule() != BtlRule.BTL_RULE_RAID);
                    seq = (int)Seqselact_Item.SEQ_SELECT_WAIT;
                    break;
                }

                case Seqselact_Item.SEQ_SELECT_WAIT:
                {
                    if (checkSelactForceQuit(null))
                    {
                        m_viewCore.CMD_ITEMSELECT_ForceQuit();
                        seq = (int)Seqselact_Item.SEQ_FORCE_QUIT;
                        break;
                    }

                    if (!m_viewCore.CMD_ITEMSELECT_Wait())
                        return false;

                    ushort itemID = (ushort)m_viewCore.CMD_ITEMSELECT_GetItemID();
                    byte targetIdx = m_viewCore.CMD_ITEMSELECT_GetTargetIdx();
                    if (calc.ITEM_IsBall(itemID))
                        registerLastSelectedBall(itemID);

                    if (!canUseItem(m_strParam, itemID, m_procPokeIdx))
                    {
                        seq = (int)Seqselact_Item.SEQ_CANT_USE_START;
                        break;
                    }

                    if (itemID != 0 && targetIdx < PokeParty.MAX_MEMBERS)
                    {
                        byte wazaIdx = m_viewCore.CMD_ITEMSELECT_GetWazaIdx();
                        byte targetID = getPokeCon().GetPartyDataConst(m_myID).GetMemberDataConst(targetIdx).GetID();
                        BTL_ACTION.SetItemParam(ref m_actionParam[m_procActionIndex], m_procPoke.GetID(), itemID, targetID, wazaIdx);
                        m_viewCore.CMD_ITEMSELECT_ReflectUsedItem();
                        if (calc.ITEM_GetParam(itemID, Pml.Item.ItemData.PrmID.ITEM_TYPE) == ItemType.BALL)
                            m_fSelActForceFinish = true;

                        selItemWork_Reserve(m_procPokeIdx, itemID, false);
                        selActSubProc_Set(selact_CheckFinish);
                        break;
                    }

                    selActSubProc_Set(selact_Root);
                    break;
                }

                case Seqselact_Item.SEQ_FORCE_QUIT:
                    if (!m_viewCore.CMD_ITEMSELECT_Wait())
                        return false;

                    selActSubProc_Set(selact_ForceQuit);
                    break;

                case Seqselact_Item.SEQ_CANT_USE_START:
                    m_viewCore.CMD_StartMsg(m_strParam);
                    seq = (int)Seqselact_Item.SEQ_CANT_USE_WAIT;
                    break;

                case Seqselact_Item.SEQ_CANT_USE_WAIT:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    selActSubProc_Set(selact_Root);
                    break;
            }

            return false;
        }
		private bool canSelectItem(global::Dpr.Battle.Logic.BTLV_STRPARAM pCantMessage) {
            if (m_mainModule.GetRule() == BtlRule.BTL_RULE_RAID && m_myParty.GetAliveMemberCount() == 0)
            {
                BTLV_STRPARAM.Setup(pCantMessage, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.RAID_Boss_13);
                return false;
            }

            return true;
        }
		private bool canUseItem(global::Dpr.Battle.Logic.BTLV_STRPARAM pCantMessage, ushort itemno, byte procPokeIdx) {
            return !calc.ITEM_IsBall(itemno) || canUseBall(pCantMessage, itemno, procPokeIdx);
        }
		private bool canUseBall(global::Dpr.Battle.Logic.BTLV_STRPARAM pCantMessage, ushort itemno, byte procPokeIdx) {
            if (m_mainModule.GetSetupStatusFlag(BTL_STATUS_FLAG.BTL_STATUS_FLAG_CANT_USE_BALL))
            {
                BTLV_STRPARAM.Setup(pCantMessage, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.Ball_NG6);
                return false;
            }

            if (m_mainModule.GetRule() == BtlRule.BTL_RULE_RAID)
            {
                BTLV_STRPARAM.Setup(pCantMessage, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.Ball_NG5);
                return false;
            }

            if (procPokeIdx != 0)
            {
                BTLV_STRPARAM.Setup(pCantMessage, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.Ball_NG3);
                return false;
            }

            if (m_mainModule.GetSetupStatusFlag(BTL_STATUS_FLAG.BTL_STATUS_FLAG_BOXFULL))
            {
                BTLV_STRPARAM.Setup(pCantMessage, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.Ball_NG2);
                return false;
            }

            if (m_mainModule.GetCompetitor(true) == BtlCompetitor.BTL_COMPETITOR_WILD && m_mainModule.GetRule() == BtlRule.BTL_RULE_DOUBLE &&
                getPokeCon().GetPartyDataConst((uint)BTL_CLIENT_ID.BTL_CLIENT_ENEMY1).GetAliveMemberCount() >= 2)
            {
                BTLV_STRPARAM.Setup(pCantMessage, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.Ball_NG1);
                return false;
            }

            if (checkBallTargetHide())
            {
                BTLV_STRPARAM.Setup(pCantMessage, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.Ball_NG4);
                return false;
            }

            if (m_mainModule.GetCompetitor(true) != BtlCompetitor.BTL_COMPETITOR_WILD)
                return true;

            BTL_POKEPARAM target = getBallTarget();
            if (target != null && (byte)target.GetValue(BTL_POKEPARAM.ValueID.BPP_LEVEL) > m_mainModule.GetCaptureLevelCap())
            {
                BTLV_STRPARAM.Setup(pCantMessage, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.Ball_NG7);
                return false;
            }

            return true;
        }
		private void registerLastSelectedBall(uint itemno) {
            if (calc.ITEM_IsBall((ushort)itemno))
                Dpr.Battle.View.Systems.BattleViewUISystem.lastSelectedBallItemNo = itemno;
        }
		private global::Dpr.Battle.Logic.BTL_POKEPARAM getBallTarget() {
            var accessor = new FrontPokeAccessor(m_mainModule, m_pBattleEnv);
            while (accessor.GetNext(out BTL_POKEPARAM bpp))
            {
                if (MainModule.PokeIDtoClientID(bpp.GetID()) == (byte)BTL_CLIENT_ID.BTL_CLIENT_ENEMY1 && bpp.IsFightEnable())
                    return bpp;
            }

            return null;
        }
		private bool checkBallTargetHide() {
            if (m_mainModule.GetCompetitor(true) != BtlCompetitor.BTL_COMPETITOR_WILD)
                return false;

            BTL_PARTY party = getPokeCon().GetPartyDataConst((uint)BTL_CLIENT_ID.BTL_CLIENT_ENEMY1);
            byte memberCount = party.GetMemberCount();
            uint frontPosNum = m_mainModule.GetFrontPosNum((byte)BTL_CLIENT_ID.BTL_CLIENT_ENEMY1);
            uint checkNum = (frontPosNum > memberCount) ? memberCount : frontPosNum;

            int aliveCount = 0;
            bool fHide = false;
            for (byte i = 0; i < checkNum; i++)
            {
                BTL_POKEPARAM bpp = party.GetMemberDataConst(i);
                if (bpp != null && !bpp.IsDead())
                {
                    aliveCount++;
                    fHide |= bpp.IsWazaHide();
                }
            }

            return fHide && aliveCount == 1;
        }
		private bool selact_Escape(ref int seq) {
            switch ((Seqselact_Escape)seq)
            {
                case Seqselact_Escape.SEQ_INIT:
                    if (!canSelectEscape(m_strParam))
                    {
                        seq = (int)Seqselact_Escape.SEQ_CANT_MSG_START;
                        return false;
                    }

                    if (needEscapeConfirm(m_strParam))
                    {
                        seq = (int)Seqselact_Escape.SEQ_CONFIRM_MSG_START;
                        return false;
                    }

                    seq = (int)Seqselact_Escape.SEQ_RETURN_ESCAPE;
                    break;

                case Seqselact_Escape.SEQ_CANT_MSG_START:
                    selact_startMsg(m_strParam);
                    seq = (int)Seqselact_Escape.SEQ_CANT_MSG_WAIT;
                    break;

                case Seqselact_Escape.SEQ_CANT_MSG_WAIT:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    selActSubProc_Set(selact_Root);
                    break;

                case Seqselact_Escape.SEQ_CONFIRM_MSG_START:
                    selact_startMsg(m_strParam);
                    seq = (int)Seqselact_Escape.SEQ_CONFIRM_MSG_WAIT;
                    break;

                case Seqselact_Escape.SEQ_CONFIRM_MSG_WAIT:
                    if (m_viewCore.CMD_WaitMsg_WithoutHide())
                    {
                        m_viewCore.CMD_YESNO_Start(true, YesNoMode.YESNO_MODE_YESNO);
                        seq = (int)Seqselact_Escape.SEQ_CONFIRM_YESNO;
                    }
                    break;

                case Seqselact_Escape.SEQ_CONFIRM_YESNO:
                {
                    if (!m_viewCore.CMD_YESNO_Wait(out BtlYesNo result))
                    {
                        if (checkSelactForceQuit(null))
                        {
                            m_viewCore.CMD_HideMsg();
                            m_viewCore.CMD_YESNO_ForceQuit();
                            m_viewCore.CMD_YESNO_Delete();
                            selActSubProc_Set(selact_ForceQuit);
                        }
                        return false;
                    }

                    m_viewCore.CMD_HideMsg();
                    if (result != BtlYesNo.BTL_YESNO_YES)
                    {
                        selActSubProc_Set(selact_Root);
                        break;
                    }

                    seq = (int)Seqselact_Escape.SEQ_RETURN_ESCAPE;
                    break;
                }

                case Seqselact_Escape.SEQ_RETURN_ESCAPE:
                    BTL_ACTION.SetEscapeParam(ref m_actionParam[m_procActionIndex], m_procPoke.GetID());
                    m_fSelActForceFinish = true;
                    selActSubProc_Set(selact_CheckFinish);
                    break;
            }

            return false;
        }
		private bool canSelectEscape(global::Dpr.Battle.Logic.BTLV_STRPARAM pCantMessage) {
            if (m_mainModule.GetRule() == BtlRule.BTL_RULE_RAID)
            {
                BTLV_STRPARAM.Setup(pCantMessage, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.EscapeProhibit);
                return false;
            }

            switch (m_mainModule.GetEscapeMode())
            {
                case BtlEscapeMode.BTL_ESCAPE_MODE_WILD:
                {
                    byte pokeID = PokeID.INVALID;
                    ushort tokuseiID = 0;
                    if (isForbidEscape(ref pokeID, ref tokuseiID) == CantEscapeCode.CANTESC_NULL)
                        return true;

                    if (tokuseiID != 0)
                    {
                        BTLV_STRPARAM.Setup(pCantMessage, BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.CantEscTok);
                        BTLV_STRPARAM.AddArg(pCantMessage, pokeID);
                        BTLV_STRPARAM.AddArg(pCantMessage, tokuseiID);
                        return false;
                    }

                    BTLV_STRPARAM.Setup(pCantMessage, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.EscapeProhibit);
                    return false;
                }

                case BtlEscapeMode.BTL_ESCAPE_MODE_NG:
                    BTLV_STRPARAM.Setup(pCantMessage, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.EscapeCant);
                    return false;

                default:
                    return true;
            }
        }
		private bool needEscapeConfirm(global::Dpr.Battle.Logic.BTLV_STRPARAM pConfirmMessage) {
            if (m_mainModule.GetEscapeMode() != BtlEscapeMode.BTL_ESCAPE_MODE_CONFIRM)
                return false;

            BTLV_STRPARAM.Setup(pConfirmMessage, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.EscapeCheck);
            return true;
        }
		private bool selact_CheckFinish(ref int seq) {
            switch (seq)
            {
                case 0:
                    m_viewCore.CMD_UI_Restart();
                    seq++;
                    return false;

                case 1:
                {
                    if (!m_viewCore.CMD_UI_WaitRestart())
                        return false;

                    m_procPokeIdx++;
                    byte numCoverPos = getMyCoverPosNum();
                    if (m_procPokeIdx < numCoverPos)
                    {
                        if (!m_fSelActForceFinish)
                        {
                            selActSubProc_Set(selact_Root);
                            return false;
                        }

                        do
                        {
                            BTL_POKEPARAM bpp = getPokeCon().GetClientPokeData(m_myID, m_procPokeIdx);
                            if (!checkActionForceSet(bpp, ref m_actionParam[m_procPokeIdx]))
                                BTL_ACTION.SetNULL(ref m_actionParam[m_procPokeIdx]);

                            m_procPokeIdx++;
                        }
                        while (m_procPokeIdx < numCoverPos);
                    }

                    setupSelActReturnData();
                    sendSelectedRaidActionIconID();
                    selActSubProc_Set(selact_Finish);
                    return false;
                }

                default:
                    return false;
            }
        }
		private void setupSelActReturnData() {
            byte numCoverPos = getMyCoverPosNum();
            byte actionNum = (byte)(numCoverPos + calcAddActionCountSum(numCoverPos));
            storeActionSelectSendData(m_actionParam, actionNum);
        }
		private void storeActionSelectSendData(global::Dpr.Battle.Logic.BTL_ACTION_PARAM[] actionParamArray, uint actionNum) {
            unsafe
            {
                fixed (BTL_ACTION_PARAM* pActionParam = &actionParamArray[0])
                {
                    m_returnData_ActionSelect->actionNum = (byte)actionNum;
                    for (int i = 0; i < actionNum; i++)
                        m_returnData_ActionSelect->actionParam[i] = (ulong)pActionParam[i].raw;
                }

                m_returnDataPtr = m_returnData_ActionSelect;
                m_returnDataSize = (uint)sizeof(ClientSendData.ACTION_SELECT);
            }
        }
		private unsafe void storeActionSelectSendData(global::Dpr.Battle.Logic.BTL_ACTION_PARAM* actionParamArray, uint actionNum) {
            m_returnData_ActionSelect->actionNum = (byte)actionNum;
            for (int i = 0; i < actionNum; i++)
                m_returnData_ActionSelect->actionParam[i] = (ulong)actionParamArray[i].raw;

            m_returnDataPtr = m_returnData_ActionSelect;
            m_returnDataSize = (uint)sizeof(ClientSendData.ACTION_SELECT);
        }
		private void sendSelectedRaidActionIconID() {
            if (m_mainModule.GetRule() != BtlRule.BTL_RULE_RAID)
                return;

            if (m_myParty.GetAliveMemberCount() == 0 && m_mainModule.IsClientNPC(m_myID))
                return;

            ref BTL_ACTION_PARAM action = ref m_actionParam[0];
            if (BTL_ACTION.IsFightWithG(ref action))
            {
                m_adapter.SetRaidAction(RaidActionIconID.G);
                return;
            }

            switch (BTL_ACTION.GetAction(action))
            {
                case BtlAction.BTL_ACTION_ITEM:
                    m_adapter.SetRaidAction(RaidActionIconID.ITEM);
                    break;

                case BtlAction.BTL_ACTION_FIGHT:
                    if (WAZADATA.GetDamageType((WazaNo)action.fight_waza) != WazaDamageType.NONE)
                        m_adapter.SetRaidAction(RaidActionIconID.WAZA_DAMAGE);
                    else
                        m_adapter.SetRaidAction(RaidActionIconID.WAZA_NOT_DAMAGE);
                    break;

                case BtlAction.BTL_ACTION_CHEER:
                    m_adapter.SetRaidAction(RaidActionIconID.CHEER);
                    break;

                default:
                    m_adapter.SetRaidAction(RaidActionIconID.NONE);
                    break;
            }
        }
		private void clearSelectedRaidActionIconID() {
            if (m_mainModule.GetRule() == BtlRule.BTL_RULE_RAID)
                m_adapter.ClearRaidAction();
        }
		private bool selact_Finish(ref int seq) {
            switch (seq)
            {
                case 0:
                    selItemWork_Quit();
                    if (m_mainModule.GetCommMode() == BtlCommMode.BTL_COMM_NONE)
                    {
                        seq += 2;
                        return false;
                    }

                    m_commWaitInfoOn = true;
                    m_viewCore.CMD_StartCommWait();
                    seq++;
                    return false;

                case 1:
                    if (m_viewCore.CMD_WaitCommWait())
                        seq++;
                    return false;

                case 2:
                    m_viewCore.CMD_UI_SelectAction_AllFinished();
                    seq++;
                    goto case 3;

                case 3:
                    if (!m_viewCore.CMD_UI_SelectAction_AllFinished_Wait())
                        return false;

                    cmdLimit_End();
                    return true;

                default:
                    return false;
            }
        }
		private void selItemWork_Init() {
            for (int i = 0; i < m_selItemWork.Length; i++)
            {
                m_selItemWork[i].itemNo = 0;
                m_selItemWork[i].bFromPokeSelect = false;
            }
        }
		private void selItemWork_Reserve(byte pokeIdx, ushort itemID, bool bFromPokeSelect) {
            if (m_bagMode != (byte)BtlBagMode.BBAG_MODE_NORMAL)
                return;

            if (m_myID == m_mainModule.GetPlayerClientID() && m_mainModule.DecrementPlayerItem(m_myID, itemID))
            {
                m_selItemWork[pokeIdx].itemNo = itemID;
                m_selItemWork[pokeIdx].bFromPokeSelect = bFromPokeSelect;
            }
        }
		private bool selItemWork_IsFromPokeSelect(byte pokeIdx) {
            if (m_bagMode == (byte)BtlBagMode.BBAG_MODE_NORMAL && m_myID == m_mainModule.GetPlayerClientID() && pokeIdx < m_selItemWork.Length)
                return m_selItemWork[pokeIdx].bFromPokeSelect;

            return false;
        }
		private void selItemWork_Restore(byte pokeIdx) {
            if (m_bagMode != (byte)BtlBagMode.BBAG_MODE_NORMAL || m_myID != m_mainModule.GetPlayerClientID())
                return;

            ushort itemID = m_selItemWork[pokeIdx].itemNo;
            if (itemID == 0)
                return;

            m_selItemWork[pokeIdx].itemNo = 0;
            m_selItemWork[pokeIdx].bFromPokeSelect = false;
            m_mainModule.AddItem(m_myID, itemID);
        }
		private void selItemWork_Quit() {
            if (m_bagMode != (byte)BtlBagMode.BBAG_MODE_NORMAL)
                return;

            for (int i = 0; i < m_selItemWork.Length; i++)
                selItemWork_Restore((byte)i);
        }
		private bool checkActionForceSet(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp, ref global::Dpr.Battle.Logic.BTL_ACTION_PARAM action) {
            if (IsCheerMode())
                return false;

            if (bpp == null || bpp.IsDead())
            {
                BTL_ACTION.SetNULL(ref action);
                return true;
            }

            if (bpp.CONTFLAG_Get(ContFlag.CONTFLG_CANT_ACTION))
            {
                BTL_ACTION.SetSkip(ref action, bpp.GetID());
                return true;
            }

            if (bpp.CheckSick(WazaSick.WAZASICK_WAZALOCK))
            {
                BTL_SICKCONT sickCont = bpp.GetSickCont(WazaSick.WAZASICK_WAZALOCK);
                WazaNo waza = (WazaNo)SICKCONT.GetParam(sickCont);
                BTL_ACTION.SetFightParam(ref action, bpp.GetID(), waza, bpp.GetPrevTargetPos());
                return true;
            }

            if (bpp.CheckSick(WazaSick.WAZASICK_TAMELOCK))
            {
                BTL_ACTION.SetFightParam(ref action, bpp.GetID(), bpp.GetPrevWazaID(), bpp.GetPrevTargetPos());
                return true;
            }

            return false;
        }
		public bool IsCheerMode() {
            return m_mainModule.GetRule() == BtlRule.BTL_RULE_RAID && m_myParty.GetAliveMemberCount() == 0;
        }
		private bool checkWazaForceSet(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp, ref global::Dpr.Battle.Logic.BTL_ACTION_PARAM action) {
            byte wazaCount = bpp.WAZA_GetCount();
            if (wazaCount != 0)
            {
                int usableWazaCount = 0;
                WazaNo usableWaza = WazaNo.NULL;
                for (byte i = 0; i < wazaCount; i++)
                {
                    if (!is_unselectable_waza(bpp, bpp.WAZA_GetID(i), null) && bpp.WAZA_GetPP(i) != 0)
                    {
                        usableWazaCount++;
                        usableWaza = bpp.WAZA_GetID(i);
                    }
                }

                if (usableWazaCount == 1)
                {
                    if (usableWaza != WazaNo.HOOBARU || Pml.Item.ItemData.IsNuts(bpp.GetItem()))
                        return false;
                }
                else if (usableWazaCount != 0)
                {
                    return false;
                }
            }

            setWaruagakiAction(ref action, bpp);
            return true;
        }
		private void setWaruagakiAction(ref global::Dpr.Battle.Logic.BTL_ACTION_PARAM dst, global::Dpr.Battle.Logic.BTL_POKEPARAM bpp) {
            ulong randContext = 0;
            BtlPokePos targetPos = calc.DecideWazaTargetAutoForClient(m_mainModule, getPokeCon(), bpp, WazaNo.WARUAGAKI, ref randContext);
            BTL_ACTION.SetFightParam(ref dst, bpp.GetID(), WazaNo.WARUAGAKI, targetPos);
        }
		private bool is_unselectable_waza(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp, global::Pml.WazaNo waza, global::Dpr.Battle.Logic.BTLV_STRPARAM strParam) {
            if (waza == WazaNo.WARUAGAKI)
                return false;

            if (!WAZADATA.IsValid(waza))
            {
                if (strParam != null)
                    BTLV_STRPARAM.Setup(strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.Waza_NG);
                return true;
            }

            ushort item = bpp.GetItemEffective(m_fldSim);
            if (item != 0)
            {
                if (bpp.CheckSick(WazaSick.WAZASICK_KODAWARI) && !bpp.IsGMode() && !GWaza.IsGWaza(waza) && tables.IsKodawariItem(item))
                {
                    WazaNo kodawariWaza = (WazaNo)SICKCONT.GetParam(bpp.GetSickCont(WazaSick.WAZASICK_KODAWARI));
                    bool isUsable = bpp.WAZA_IsUsable(kodawariWaza);
                    if (kodawariWaza != waza && isUsable)
                    {
                        if (strParam != null)
                        {
                            BTLV_STRPARAM.Setup(strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.KodawariLock);
                            BTLV_STRPARAM.AddArg(strParam, item);
                            BTLV_STRPARAM.AddArg(strParam, (int)kodawariWaza);
                        }
                        return true;
                    }
                }

                if (item == (ushort)ItemNo.TOTUGEKITYOKKI && !WAZADATA.IsDamage(waza))
                {
                    if (strParam != null)
                    {
                        BTLV_STRPARAM.Setup(strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.TotsugekiLock);
                        BTLV_STRPARAM.AddArg(strParam, item);
                    }
                    return true;
                }
            }

            if (bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI_EFFECTIVE) == (int)TokuseiNo.GORIMUTYUU &&
                bpp.CheckSick(WazaSick.WAZASICK_KODAWARI) && !bpp.IsGMode() && !GWaza.IsGWaza(waza))
            {
                WazaNo kodawariWaza = (WazaNo)SICKCONT.GetParam(bpp.GetSickCont(WazaSick.WAZASICK_KODAWARI));
                bool isUsable = bpp.WAZA_IsUsable(kodawariWaza);
                if (kodawariWaza != waza && isUsable)
                {
                    if (strParam != null)
                    {
                        BTLV_STRPARAM.Setup(strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.WazaLock);
                        BTLV_STRPARAM.AddArg(strParam, bpp.GetID());
                        BTLV_STRPARAM.AddArg(strParam, (int)kodawariWaza);
                    }
                    return true;
                }
            }

            if (bpp.CheckSick(WazaSick.WAZASICK_ENCORE))
            {
                WazaNo encoreWaza = (WazaNo)SICKCONT.GetParam(bpp.GetSickCont(WazaSick.WAZASICK_ENCORE));
                if (encoreWaza != waza && !GWaza.IsGWaza(waza))
                {
                    if (strParam != null)
                    {
                        BTLV_STRPARAM.Setup(strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.WazaLock);
                        BTLV_STRPARAM.AddArg(strParam, bpp.GetID());
                        BTLV_STRPARAM.AddArg(strParam, (int)encoreWaza);
                    }
                    return true;
                }
            }

            int strID = -1;
            if (bpp.CheckSick(WazaSick.WAZASICK_TYOUHATSU) && !WAZADATA.IsDamage(waza))
                strID = BTL_STRID_SET.ChouhatuWarn;
            else if (bpp.CheckSick(WazaSick.WAZASICK_ICHAMON) && bpp.GetPrevOrgWazaID() == waza && !bpp.IsGMode())
                strID = BTL_STRID_SET.IchamonWarn;
            else if (bpp.CheckSick(WazaSick.WAZASICK_KANASIBARI) && bpp.GetSickParam(WazaSick.WAZASICK_KANASIBARI) == (ushort)waza && !GWaza.IsGWaza(waza))
                strID = BTL_STRID_SET.KanasibariWarn;
            else if (bpp.CheckSick(WazaSick.WAZASICK_KAIHUKUHUUJI) && WAZADATA.GetFlag(waza, WazaFlag.KAIFUKU_HUUJI))
                strID = BTL_STRID_SET.KaifukuFujiWarn;
            else if (m_fldSim.CheckEffect(EffectType.EFF_FUIN) && !bpp.IsGMode() && m_fldSim.CheckFuin(m_mainModule, getPokeCon(), bpp, waza))
                strID = BTL_STRID_SET.FuuinWarn;
            else if (m_fldSim.CheckEffect(EffectType.EFF_JURYOKU) && !bpp.IsGMode() && WAZADATA.GetFlag(waza, WazaFlag.FLYING))
                strID = BTL_STRID_SET.JyuryokuWazaFail;

            if (strID >= 0)
            {
                if (strParam != null)
                {
                    BTLV_STRPARAM.Setup(strParam, BtlStrType.BTL_STRTYPE_SET, (ushort)strID);
                    BTLV_STRPARAM.AddArg(strParam, bpp.GetID());
                    BTLV_STRPARAM.AddArg(strParam, (int)waza);
                }
                return true;
            }

            if (waza == WazaNo.HOOBARU)
            {
                if (!Pml.Item.ItemData.IsNuts(bpp.GetItem()))
                {
                    if (strParam != null)
                    {
                        BTLV_STRPARAM.Setup(strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.Hoobaru_Failed);
                        BTLV_STRPARAM.AddArg(strParam, bpp.GetID());
                    }
                    return true;
                }
            }
            else if (waza == WazaNo.GEPPU && !bpp.PERMFLAG_Get(BTL_POKEPARAM.PermFlag.PERMFLAG_ATE_KINOMI))
            {
                if (strParam != null)
                {
                    BTLV_STRPARAM.Setup(strParam, BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.GeppuFail);
                    BTLV_STRPARAM.AddArg(strParam, bpp.GetID());
                }
                return true;
            }

            if (m_mainModule.IsSkyBattle() && WAZADATA.GetFlag(waza, WazaFlag.SKY_BATTLE_FAIL))
            {
                if (strParam != null)
                    BTLV_STRPARAM.Setup(strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.SkyBattleFail);
                return true;
            }

            if (bpp.CheckSick(WazaSick.WAZASICK_ZIGOKUDUKI) && !bpp.IsGMode() && WAZADATA.GetFlag(waza, WazaFlag.SOUND))
            {
                if (strParam != null)
                {
                    BTLV_STRPARAM.Setup(strParam, BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Zigokuduki_Warn);
                    BTLV_STRPARAM.AddArg(strParam, bpp.GetID());
                }
                return true;
            }

            return false;
        }
		private bool is_unselectable_target(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp, global::Pml.WazaNo waza, global::Dpr.Battle.Logic.BtlPokePos targetPos, global::Dpr.Battle.Logic.BTLV_STRPARAM strParam) {
            if (waza != WazaNo.KAHUNDANGO || !bpp.CheckSick(WazaSick.WAZASICK_KAIHUKUHUUJI))
                return false;

            BtlPokePos myPos = m_mainModule.PokeIDtoPokePos(getPokeCon(), bpp.GetID());
            if (!m_mainModule.IsFriendPokePos(myPos, targetPos))
                return false;

            if (strParam != null)
            {
                BTLV_STRPARAM.Setup(strParam, BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.KaifukuFujiWarn);
                BTLV_STRPARAM.AddArg(strParam, bpp.GetID());
                BTLV_STRPARAM.AddArg(strParam, (int)WazaNo.KAHUNDANGO);
            }
            return true;
        }
		private byte storeSelectableWazaFlag(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp, bool checkGWaza, bool[] dst) {
            byte wazaCount = bpp.WAZA_GetCount();
            byte firstSelectableIdx = BattleDefConst.PTL_WAZA_MAX;

            for (byte i = 0; i < wazaCount; i++)
            {
                if (bpp.WAZA_GetPP(i) == 0)
                {
                    dst[i] = false;
                    continue;
                }

                WazaNo waza = bpp.WAZA_GetID(i);
                if (checkGWaza)
                    waza = GWaza.GetGWaza(waza);

                bool isUnselectable = is_unselectable_waza(bpp, waza, null);
                dst[i] = !isUnselectable;
                if (!isUnselectable && firstSelectableIdx == BattleDefConst.PTL_WAZA_MAX)
                    firstSelectableIdx = i;
            }

            for (int i = wazaCount; i < BattleDefConst.PTL_WAZA_MAX; i++)
                dst[i] = false;

            return firstSelectableIdx;
        }
		public global::Dpr.Battle.Logic.BTL_CLIENT.CantEscapeCode isForbidPokeChange(global::Dpr.Battle.Logic.BTL_POKEPARAM procPoke, out byte pokeID, out ushort tokuseiID) {
            pokeID = PokeID.INVALID;
            tokuseiID = 0;

            if (procPoke.GetItemEffective(m_fldSim) == (ushort)ItemNo.KIREINANUKEGARA)
                return CantEscapeCode.CANTESC_NULL;

            return checkForbidChangeEscapeCommon(procPoke, ref pokeID, ref tokuseiID);
        }
		public global::Dpr.Battle.Logic.BTL_CLIENT.CantEscapeCode isForbidEscape(ref byte pokeID, ref ushort tokuseiID) {
            byte numCoverPos = getMyCoverPosNum();
            for (byte i = 0; i < numCoverPos; i++)
            {
                BTL_POKEPARAM bpp = m_myParty.GetMemberDataConst(i);
                if (bpp.IsDead())
                    continue;

                if (bpp.GetItemEffective(m_fldSim) == (ushort)ItemNo.KEMURIDAMA)
                    return CantEscapeCode.CANTESC_NULL;

                if (bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI_EFFECTIVE) == (int)TokuseiNo.NIGEASI)
                    return CantEscapeCode.CANTESC_NULL;
            }

            for (byte i = 0; i < numCoverPos; i++)
            {
                CantEscapeCode code = checkForbidChangeEscapeCommon(m_myParty.GetMemberDataConst(i), ref pokeID, ref tokuseiID);
                if (code != CantEscapeCode.CANTESC_NULL)
                    return code;
            }

            return CantEscapeCode.CANTESC_NULL;
        }
		private global::Dpr.Battle.Logic.BTL_CLIENT.CantEscapeCode checkForbidChangeEscapeCommon(global::Dpr.Battle.Logic.BTL_POKEPARAM procPoke, ref byte pokeID, ref ushort tokuseiID) {
            byte[] pokeIDAry = new byte[DefineConstants.BTL_POSIDX_MAX];

            if (procPoke.IsMatchType((byte)PokeType.GHOST))
                return CantEscapeCode.CANTESC_NULL;

            if (m_fldSim.CheckRemainingTurn(EffectType.EFF_FAIRY_LOCK) == 1)
                return CantEscapeCode.CANTESC_FAIRY_LOCK;

            BtlPokePos myPos = m_mainModule.PokeIDtoPokePos(getPokeCon(), procPoke.GetID());
            var exPos = new ExPokePos(ExPokePos.ExPosType.AREA_ENEMY, myPos);
            byte pokeCount = exPos.ExpandExistPokeID(m_mainModule.GetRule(), m_mainModule.GetMultiMode(), getPokeCon(), pokeIDAry);
            for (int i = 0; i < pokeCount; i++)
            {
                BTL_POKEPARAM bpp = getPokeCon().GetPokeParamConst(pokeIDAry[i]);
                ushort tokusei = (ushort)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI_EFFECTIVE);
                switch ((TokuseiNo)tokusei)
                {
                    case TokuseiNo.ARIZIGOKU:
                        if (checkForbitEscapeEffective_Arijigoku(procPoke))
                        {
                            pokeID = bpp.GetID();
                            tokuseiID = (ushort)TokuseiNo.ARIZIGOKU;
                            return CantEscapeCode.CANTESC_KAGEFUMI;
                        }
                        break;

                    case TokuseiNo.ZIRYOKU:
                        if (checkForbitEscapeEffective_Jiryoku(procPoke))
                        {
                            pokeID = bpp.GetID();
                            tokuseiID = (ushort)TokuseiNo.ZIRYOKU;
                            return CantEscapeCode.CANTESC_KAGEFUMI;
                        }
                        break;

                    case TokuseiNo.KAGEHUMI:
                        if (checkForbitEscapeEffective_Kagefumi(procPoke))
                        {
                            pokeID = bpp.GetID();
                            tokuseiID = (ushort)TokuseiNo.KAGEHUMI;
                            return CantEscapeCode.CANTESC_KAGEFUMI;
                        }
                        break;
                }
            }

            if (procPoke.CheckSick(WazaSick.WAZASICK_TOOSENBOU) || procPoke.CheckSick(WazaSick.WAZASICK_BIND) || procPoke.CheckSick(WazaSick.WAZASICK_NEWOHARU))
            {
                pokeID = procPoke.GetID();
                tokuseiID = 0;
                return CantEscapeCode.CANTESC_TOOSENBOU;
            }

            return CantEscapeCode.CANTESC_NULL;
        }
		private bool checkForbitEscapeEffective_Kagefumi(global::Dpr.Battle.Logic.BTL_POKEPARAM procPoke) {
            return procPoke.GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI_EFFECTIVE) != (int)TokuseiNo.KAGEHUMI;
        }
		private bool checkForbitEscapeEffective_Arijigoku(global::Dpr.Battle.Logic.BTL_POKEPARAM procPoke) {
            ushort item = procPoke.GetItemEffective(m_fldSim);
            if (m_fldSim.CheckEffect(EffectType.EFF_JURYOKU) || procPoke.CheckSick(WazaSick.WAZASICK_FLYING_CANCEL))
                return true;

            bool isNewoharu = procPoke.CheckSick(WazaSick.WAZASICK_NEWOHARU);
            if (item == (ushort)ItemNo.KUROITEKKYUU || isNewoharu)
                return true;

            if (procPoke.GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI_EFFECTIVE) == (int)TokuseiNo.HUYUU)
                return false;

            if (procPoke.IsMatchType((byte)PokeType.HIKOU) || procPoke.CheckSick(WazaSick.WAZASICK_FLYING) || procPoke.CheckSick(WazaSick.WAZASICK_TELEKINESIS))
                return false;

            return item != (ushort)ItemNo.HUUSEN;
        }
		private bool checkForbitEscapeEffective_Jiryoku(global::Dpr.Battle.Logic.BTL_POKEPARAM procPoke) {
            return procPoke.IsMatchType((byte)PokeType.HAGANE);
        }
		private void changeAI_InitWork() {
            for (int i = 0; i < m_AIChangeIndex.Length; i++)
                m_AIChangeIndex[i] = -1;
