		private global::Dpr.Battle.Logic.BTL_POKEPARAM changeAI_SupposeEnemy(global::Dpr.Battle.Logic.BtlPokePos basePos) {
            var exPos = new ExPokePos(ExPokePos.ExPosType.AREA_ENEMY, basePos);
            byte[] pokeIDAry = new byte[DefineConstants.BTL_POSIDX_MAX];
            byte pokeCount = exPos.ExpandExistPokeID(m_mainModule.GetRule(), m_mainModule.GetMultiMode(), getPokeCon(), pokeIDAry);
            if (pokeCount == 0)
                return null;

            ulong idx = m_AIRand.GetValue(pokeCount);
            return getPokeCon().GetPokeParam(pokeIDAry[idx]);
        }
		private bool SubProc_AI_SelectAction(ref int seq) {
            switch ((SEQ_SubProc_AI_SelectAction)seq)
            {
                case SEQ_SubProc_AI_SelectAction.SEQ_INIT:
                    clearSelectedRaidActionIconID();
                    changeAI_InitWork();
                    BattleAiSystem.SetCommonRand(m_AIRand.GetValue(BattleAiSystem.BASIC_RAND_RANGE));
                    m_actCountSum = 0;
                    m_procPokeIdx = 0;
                    m_procPokeActIdx = 0;
                    selact_ClearWorks();
                    if (IsCheerMode())
                    {
                        seq = (int)SEQ_SubProc_AI_SelectAction.SEQ_END;
                        goto case SEQ_SubProc_AI_SelectAction.SEQ_END;
                    }

                    seq = (int)SEQ_SubProc_AI_SelectAction.SEQ_POKE_START;
                    goto case SEQ_SubProc_AI_SelectAction.SEQ_POKE_START;

                case SEQ_SubProc_AI_SelectAction.SEQ_POKE_START:
                    m_procPoke = getPokeCon().GetClientPokeData(m_myID, m_procPokeIdx);
                    m_procActionIndex = m_actCountSum;
                    if (m_mainModule.GetRule() == BtlRule.BTL_RULE_SAFARI)
                    {
                        seq = (int)SEQ_SubProc_AI_SelectAction.SEQ_SAFARI;
                        goto case SEQ_SubProc_AI_SelectAction.SEQ_SAFARI;
                    }

                    if (checkActionForceSet(m_procPoke, ref m_actionParam[m_actCountSum]))
                    {
                        seq = (int)SEQ_SubProc_AI_SelectAction.SEQ_NEXT_POKE;
                        goto case SEQ_SubProc_AI_SelectAction.SEQ_NEXT_POKE;
                    }

                    if (m_procPoke.IsRaidBoss() && isRaidBossGWazaUseTurn(m_procPoke) && m_procPokeActIdx == 0)
                    {
                        decideRaidBossGWazaAction(ref m_actionParam[m_procActionIndex]);
                        seq = (int)SEQ_SubProc_AI_SelectAction.SEQ_NEXT_POKE;
                        goto case SEQ_SubProc_AI_SelectAction.SEQ_NEXT_POKE;
                    }

                    seq = (int)SEQ_SubProc_AI_SelectAction.SEQ_AI_START;
                    goto case SEQ_SubProc_AI_SelectAction.SEQ_AI_START;

                case SEQ_SubProc_AI_SelectAction.SEQ_AI_START:
                {
                    bool isGoingToStartG = canStartGForNPC(m_procPoke);
                    bool isGMode = m_procPoke.IsGMode();
                    var startParam = new BattleAi.StartParam();
                    startParam.pokeId = m_procPoke.GetID();
                    startParam.itemId = AIItem_CheckUse(m_procPoke, m_myParty);
                    startParam.isGoingToStartG = isGoingToStartG;
                    storeSelectableWazaFlag(m_procPoke, isGoingToStartG || isGMode, startParam.selectableWazaFlags);
                    m_ai.StartActionSelect(startParam);
                    seq = (int)SEQ_SubProc_AI_SelectAction.SEQ_AI_WAIT;
                    goto case SEQ_SubProc_AI_SelectAction.SEQ_AI_WAIT;
                }

                case SEQ_SubProc_AI_SelectAction.SEQ_AI_WAIT:
                {
                    m_ai.UpdateActionSelect();
                    if (!m_ai.IsActionSelectFinished())
                        return false;

                    BattleAi.Result aiResult = m_ai.GetResult();
                    buildActionParamFromAiResult(ref m_actionParam[m_procActionIndex], m_procPokeIdx, m_procPoke, m_myParty, aiResult);
                    if (BTL_ACTION.IsFightWithG(ref m_actionParam[m_procActionIndex]))
                        m_isGSelectedThisTurn = true;

                    if (aiResult.action == BattleAi.AiAction.AIACT_POKECHANGE)
                        changeAI_SetReserve(m_procPokeIdx, aiResult.changePokeIndex);

                    seq = (int)SEQ_SubProc_AI_SelectAction.SEQ_NEXT_POKE;
                    goto case SEQ_SubProc_AI_SelectAction.SEQ_NEXT_POKE;
                }

                case SEQ_SubProc_AI_SelectAction.SEQ_NEXT_POKE:
                    m_actCountSum++;
                    m_procPokeActIdx++;
                    if (m_procPokeActIdx < getAIPokeActNum(m_procPoke))
                    {
                        seq = (int)SEQ_SubProc_AI_SelectAction.SEQ_POKE_START;
                        goto case SEQ_SubProc_AI_SelectAction.SEQ_POKE_START;
                    }

                    m_procPokeIdx++;
                    if (m_procPokeIdx < getMyCoverPosNum())
                    {
                        seq = (int)SEQ_SubProc_AI_SelectAction.SEQ_POKE_START;
                        goto case SEQ_SubProc_AI_SelectAction.SEQ_POKE_START;
                    }

                    seq = (int)SEQ_SubProc_AI_SelectAction.SEQ_END;
                    goto case SEQ_SubProc_AI_SelectAction.SEQ_END;

                case SEQ_SubProc_AI_SelectAction.SEQ_SAFARI:
                    buildActionParam_Safari(ref m_actionParam[m_procActionIndex], m_procPokeIdx, m_procPoke);
                    m_actCountSum++;
                    m_procPokeActIdx++;
                    seq = (int)SEQ_SubProc_AI_SelectAction.SEQ_END;
                    goto case SEQ_SubProc_AI_SelectAction.SEQ_END;

                case SEQ_SubProc_AI_SelectAction.SEQ_END:
                    storeActionSelectSendData(m_actionParam, m_actCountSum);
                    sendSelectedRaidActionIconID();
                    return true;

                default:
                    return false;
            }
        }
		private byte getAIPokeActNum(global::Dpr.Battle.Logic.BTL_POKEPARAM pPoke) {
            if (pPoke.IsRaidBoss())
                return pPoke.GetRaidBossParam().GetActionNum();

            return 1;
        }
		private global::Dpr.Battle.Logic.BTL_ACTION_PARAM buildActionParamFromAiResult(ref global::Dpr.Battle.Logic.BTL_ACTION_PARAM actionParam, byte actPokeIndex, global::Dpr.Battle.Logic.BTL_POKEPARAM actPoke, global::Dpr.Battle.Logic.BTL_PARTY actPokeParty, in global::Dpr.Battle.Logic.BattleAi.Result aiResult) {
            switch (aiResult.action)
            {
                case BattleAi.AiAction.AIACT_WAZA:
                    buildActionParamFromAiResult_Fight(ref actionParam, actPoke, aiResult);
                    break;

                case BattleAi.AiAction.AIACT_ITEM:
                {
                    byte targetID = m_myParty.GetMemberDataConst(actPokeIndex).GetID();
                    BTL_ACTION.SetItemParam(ref actionParam, actPoke.GetID(), aiResult.itemId, targetID, 0);
                    break;
                }

                case BattleAi.AiAction.AIACT_POKECHANGE:
                    BTL_ACTION.SetChangeParam(ref actionParam, actPokeIndex, aiResult.changePokeIndex);
                    break;

                case BattleAi.AiAction.AIACT_ESCAPE:
                    BTL_ACTION.SetEscapeParam(ref actionParam, actPoke.GetID());
                    break;

                case BattleAi.AiAction.AIACT_WARUAGAKI:
                    setWaruagakiAction(ref actionParam, actPoke);
                    break;

                default:
                    BTL_ACTION.SetSkip(ref actionParam, actPoke.GetID());
                    break;
            }

            return actionParam;
        }
		private void buildActionParamFromAiResult_Fight(ref global::Dpr.Battle.Logic.BTL_ACTION_PARAM actionParam, global::Dpr.Battle.Logic.BTL_POKEPARAM actPoke, in global::Dpr.Battle.Logic.BattleAi.Result aiResult) {
            WazaNo waza = actPoke.WAZA_GetID(aiResult.wazaIndex);
            bool forbidGWaza = actPoke.IsRaidBoss();
            BTL_ACTION.SetFightParam(ref actionParam, actPoke.GetID(), waza, aiResult.wazaTargetPos, forbidGWaza);

            if (canStartGForNPC(actPoke))
                actionParam.fight_gFlag = true;
        }
		private void buildActionParam_Safari(ref global::Dpr.Battle.Logic.BTL_ACTION_PARAM actionParam, byte actPokeIndex, global::Dpr.Battle.Logic.BTL_POKEPARAM actPoke) {
            int escapeCount = (int)m_pBattleEnv.GetBattleCounter().Get(BattleCounter.UniqueCounter.SAFARI_ESCAPE_COUNT);
            if (Safari.JudgeSafariEscape((MonsNo)actPoke.GetMonsNo(), actPoke.GetFormNo(), escapeCount))
                BTL_ACTION.SetEscapeParam(ref actionParam, actPoke.GetID());
            else
                BTL_ACTION.SetSafariYousumi(ref actionParam, actPoke.GetID());
        }
		private bool canStartGForNPC(global::Dpr.Battle.Logic.BTL_POKEPARAM pActPoke) {
            return GMode.CanStartG(m_mainModule, m_pBattleEnv, (BTL_CLIENT_ID)m_myID) && !m_isGSelectedThisTurn && pActPoke.CanStartG() &&
                   m_mainModule.IsGEnableByNPC(pActPoke.GetID());
        }
		private void decideRaidBossGWazaAction(ref global::Dpr.Battle.Logic.BTL_ACTION_PARAM destAction) {
            BtlPokePos targetPos = decideRaidBossGWazaTarget();
            BTL_POKEPARAM target = getPokeCon().GetFrontPokeDataConst(targetPos);
            BTL_POKEPARAM boss = getPokeCon().GetClientPokeData(m_myID, 0);
            WazaNo waza = decideRaidBossWaza(boss, target);
            bool forbidGWaza = !WAZADATA.IsDamage(waza);
            BTL_ACTION.SetFightParam(ref destAction, boss.GetID(), waza, targetPos, forbidGWaza);
        }
		private global::Dpr.Battle.Logic.BtlPokePos decideRaidBossGWazaTarget() {
            var selectParam = new RaidBoss.SelectTargetParam();
            selectParam.pBattleEnv = m_pBattleEnv;
            selectParam.pRandom = m_AIRand;
            return RaidBoss.SelectTargetPos(selectParam);
        }
		private void correctRaidBossGWazaTarget_JK3(global::Dpr.Battle.Logic.RaidBoss.SelectTargetParam pSelectParam) {
            pSelectParam.equalizeWeight = true;
            if (GetTurnCount() == 0 || (m_JK3Joker_PrevTurnAttackToLegends != 0 && GetTurnCount() - m_JK3Joker_PrevTurnAttackToLegends <= 2))
            {
                pSelectParam.isSelectEnable[0] = true;
                pSelectParam.isSelectEnable[1] = true;
                pSelectParam.isSelectEnable[2] = false;
                pSelectParam.isSelectEnable[3] = false;
                return;
            }

            ulong rand = m_AIRand.GetValue(2);
            uint turnCount = GetTurnCount();
            bool attackToLegends = rand == 0 || turnCount == 1;
            pSelectParam.isSelectEnable[0] = !attackToLegends;
            pSelectParam.isSelectEnable[1] = !attackToLegends;
            pSelectParam.isSelectEnable[2] = attackToLegends;
            pSelectParam.isSelectEnable[3] = attackToLegends;
            if (attackToLegends)
                m_JK3Joker_PrevTurnAttackToLegends = GetTurnCount();
        }
		private global::Pml.WazaNo decideRaidBossWaza(global::Dpr.Battle.Logic.BTL_POKEPARAM boss, global::Dpr.Battle.Logic.BTL_POKEPARAM target) {
            byte wazaCount = boss.WAZA_GetCount();
            byte atkPokeID = boss.GetID();
            byte defPokeID = target.GetID();
            uint[] damage = new uint[BattleDefConst.PTL_WAZA_MAX];
            for (byte i = 0; i < wazaCount; i++)
                damage[i] = m_battleSimulator.CalcDamage(atkPokeID, defPokeID, boss.WAZA_GetID(i), true, false);

            byte maxIdx = 0;
            byte maxDamage = (byte)damage[0];
            for (byte i = 1; i < wazaCount; i++)
            {
                if (damage[i] > maxDamage)
                {
                    maxDamage = (byte)damage[i];
                    maxIdx = i;
                }
            }

            return boss.WAZA_GetID(maxIdx);
        }
		private bool isRaidBossGWazaUseTurn(global::Dpr.Battle.Logic.BTL_POKEPARAM boss) {
            return boss.GetRaidBossParam().IsOnGWazaUseTurn();
        }
		private bool canRaidBossUseGWazaIfNotG(global::Dpr.Battle.Logic.BTL_POKEPARAM boss) {
            return false;
        }
		public byte countPuttablePokemons(byte[] list) {
            byte numCoverPos = getMyCoverPosNum();
            byte numFrontPos = calc.RULE_HandPokeIndex(m_mainModule.GetRule(), numCoverPos);
            return countPuttablePokemons_sub(list, numFrontPos);
        }
		private byte countPuttablePokemons_sub(byte[] list, byte numFrontPos) {
            byte count = 0;
            byte memberCount = m_myParty.GetMemberCount();
            for (byte i = numFrontPos; i < memberCount; i++)
            {
                if (m_myParty.GetMemberDataConst(i).IsFightEnable())
                {
                    if (list != null)
                        list[count] = i;

                    count++;
                }
            }

            return count;
        }
		private unsafe void sortPuttablePokemonList(byte* list, byte numPoke, global::Dpr.Battle.Logic.BTL_POKEPARAM target, global::Dpr.Battle.Logic.BtlPokePos posForCheckEffect) {
            int[] score = new int[PokeParty.MAX_MEMBERS];

            for (int i = 0; i < numPoke; i++)
            {
                score[i] = 0;
                BTL_POKEPARAM bpp = m_myParty.GetMemberDataConst(list[i]);
                if (bpp.IsDead())
                {
                    score[i] = -2;
                    continue;
                }

                if (changeAI_IsSpecialMons(bpp) || !CanChangePoke(bpp))
                {
                    score[i] = -1;
                    continue;
                }

                if (target != null)
                {
                    byte wazaCount = bpp.WAZA_GetCount();
                    for (byte w = 0; w < wazaCount; w++)
                    {
                        if (bpp.WAZA_GetPP(w) == 0)
                            continue;

                        WazaNo waza = bpp.WAZA_GetID(w);
                        if (!WAZADATA.IsDamage(waza))
                            continue;

                        byte wazaType = WAZADATA.GetType(waza);
                        uint power = WAZADATA.GetPower(waza);
                        if ((int)power < 10)
                            power = 60;

                        Pml.Battle.TypeAffinity.AffinityID aff = calc.TypeAffPair(wazaType, target.GetPokeType());
                        int damage = (int)calc.AffDamage(power, aff);
                        if (score[i] < damage)
                            score[i] = damage;
                    }
                }

                if (isExistHPRecoverEffect(posForCheckEffect))
                {
                    int hpRatio = bpp.GetHPRatio();
                    if (hpRatio <= 0x42AB8)
                        score[i] += (int)(FX32.ToFloat(0x64000 - hpRatio) + 2000.0);
                }
            }

            for (int i = 0; i < numPoke; i++)
            {
                for (int j = i + 1; j < numPoke; j++)
                {
                    if (score[i] < score[j])
                    {
                        int tmpScore = score[i];
                        score[i] = score[j];
                        score[j] = tmpScore;

                        byte tmpIdx = list[i];
                        list[i] = list[j];
                        list[j] = tmpIdx;
                    }
                }
            }
        }
		private bool changeAI_IsSpecialMons(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp) {
            return m_mainModule.IsCompetitorScenarioMode() && m_mainModule.IsGEnableByNPC(bpp.GetID());
        }
		private bool isExistHPRecoverEffect(global::Dpr.Battle.Logic.BtlPokePos pos) {
            if (pos >= BtlPokePos.POS_NULL)
                return false;

            if (m_pBattleEnv.GetPosEffectStatus(pos, BtlPosEffect.BTL_POSEFF_IYASINONEGAI).IsEffective())
                return true;

            return m_pBattleEnv.GetPosEffectStatus(pos, BtlPosEffect.BTL_POSEFF_MIKADUKINOMAI).IsEffective();
        }
		private void setupPokeSelParam(byte numSelect, global::Dpr.Battle.Logic.PokeSelParam param, global::Dpr.Battle.Logic.PokeSelResult result) {
            byte numCoverPos = getMyCoverPosNum();
            param.Init((BTL_CLIENT_ID)m_myID, m_myParty, numSelect);
            param.SetProhibitFighting(numCoverPos);
            result.Init(param);
        }
		private void storePokeSelResult(global::Dpr.Battle.Logic.PokeSelResult res) {
            for (int i = 0; i < res.m_cnt; i++)
                BTL_ACTION.SetChangeParam(ref m_actionParam[i], res.m_outPokeIdx[i], res.m_selIdx[i]);

            storeActionSelectSendData(m_actionParam, res.m_cnt);
        }
		private void storePokeSelResult_ForceQuit() {
            byte memberCount = m_myParty.GetMemberCount();
            byte startIdx = m_mainModule.GetClientBenchPosIndex(m_myID);
            byte actionCount = 0;

            for (int i = 0; i < m_myChangePokeCnt; i++)
            {
                m_mainModule.BtlPosToClientID_and_PosIdx(m_myChangePokePos[i], out byte clientID, out byte posIdx);
                for (byte memberIdx = startIdx; memberIdx < memberCount; memberIdx++)
                {
                    if (!m_myParty.GetMemberDataConst(memberIdx).IsDead())
                    {
                        BTL_ACTION.SetChangeParam(ref m_actionParam[actionCount++], posIdx, memberIdx);
                        startIdx = (byte)(memberIdx + 1);
                        break;
                    }
                }
            }

            storeActionSelectSendData(m_actionParam, actionCount);
        }
		private byte storeMyChangePokePos(global::Dpr.Battle.Logic.BtlPokePos[] myCoverPos) {
            byte count = 0;
            unsafe
            {
                byte* recvData = null;
                m_adapter.GetRecvData((void**)&recvData);
                for (byte i = 0; i < recvData[0]; i++)
                {
                    BtlPokePos pos = (BtlPokePos)recvData[i + 1];
                    if (m_myID == m_mainModule.BtlPosToClientID(pos))
                        myCoverPos[count++] = pos;
                }
            }

            return count;
        }
		private bool SubProc_UI_SelectChangeOrEscape(ref int seq) {
            switch (seq)
            {
                case 0:
                    m_viewCore.CMD_YESNO_Start(false, YesNoMode.YESNO_MODE_NEXT_POKE);
                    seq++;
                    return false;

                case 1:
                    if (!m_viewCore.CMD_YESNO_Wait(out BtlYesNo result))
                        return false;

                    unsafe
                    {
                        *m_change_escape_code = (byte)(result != BtlYesNo.BTL_YESNO_YES ? 1 : 0);
                        m_returnDataPtr = m_change_escape_code;
                        m_returnDataSize = sizeof(byte);
                    }
                    return true;

                default:
                    return false;
            }
        }
		private bool SubProc_UI_SelectPokemonForCover(ref int seq) {
            return selectPokemonUI_Core(ref seq, false);
        }
		private bool SubProc_UI_SelectPokemonForChange(ref int seq) {
            return selectPokemonUI_Core(ref seq, true);
        }
		private bool SubProc_AI_SelectPokemon(ref int seq) {
            m_myChangePokeCnt = storeMyChangePokePos(m_myChangePokePos);
            if (m_myChangePokeCnt == 0)
            {
                BTL_ACTION.SetNULL(ref m_actionParam[0]);
                storeActionSelectSendData(m_actionParam, 1);
                return true;
            }

            byte[] puttableList = new byte[PokeParty.MAX_MEMBERS];
            byte numPuttable = countPuttablePokemons(puttableList);
            if (numPuttable == 0)
            {
                BTL_ACTION.SetChangeDepleteParam(ref m_actionParam[0]);
                storeActionSelectSendData(m_actionParam, 1);
                return true;
            }

            byte numSelect = (m_myChangePokeCnt > numPuttable) ? numPuttable : m_myChangePokeCnt;
            sortChangePos(m_myChangePokePos, m_myChangePokeCnt);

            unsafe
            {
                fixed (byte* pList = &puttableList[0])
                {
                    for (byte i = 0; i < numSelect; i++)
                    {
                        m_mainModule.BtlPosToClientID_and_PosIdx(m_myChangePokePos[i], out byte clientID, out byte posIdx);
                        BTL_POKEPARAM target = changeAI_SupposeEnemy(m_myChangePokePos[i]);
                        sortPuttablePokemonList(pList + i, (byte)(numPuttable - i), target, m_myChangePokePos[i]);
                        BTL_ACTION.SetChangeParam(ref m_actionParam[i], posIdx, puttableList[i]);
                    }
                }
            }

            storeActionSelectSendData(m_actionParam, numSelect);
            return true;
        }
		private void sortChangePos(global::Dpr.Battle.Logic.BtlPokePos[] posAry, uint posCnt) {
            if (posCnt < 2)
                return;

            byte[] hpRecoverFlags = new byte[DefineConstants.BTL_POSIDX_MAX];
            uint num = System.Math.Min(posCnt, (uint)hpRecoverFlags.Length);
            for (int i = 0; i < num; i++)
                hpRecoverFlags[i] = (byte)(isExistHPRecoverEffect(posAry[i]) ? 1 : 0);

            for (int i = 0; i < num; i++)
            {
                byte maxIdx = (byte)i;
                byte maxValue = hpRecoverFlags[i];
                for (int j = i + 1; j < num; j++)
                {
                    if (hpRecoverFlags[j] > maxValue)
                    {
                        maxValue = hpRecoverFlags[j];
                        maxIdx = (byte)j;
                    }
                }

                if (maxIdx != i)
                {
                    byte tmpFlag = hpRecoverFlags[i];
                    hpRecoverFlags[i] = hpRecoverFlags[maxIdx];
                    hpRecoverFlags[maxIdx] = tmpFlag;

                    BtlPokePos tmpPos = posAry[i];
                    posAry[i] = posAry[maxIdx];
                    posAry[maxIdx] = tmpPos;
                }
            }
        }
		private bool SubProc_REC_SelectPokemon(ref int seq) {
            return SubProc_REC_SelectAction(ref seq);
        }
		private bool selectPokemonUI_Core(ref int seq, bool bForceChangeMode) {
            switch ((SeqselectPokemonUI_Core)seq)
            {
                case SeqselectPokemonUI_Core.SEQ_INIT:
                {
                    m_myChangePokeCnt = storeMyChangePokePos(m_myChangePokePos);
                    if (m_myChangePokeCnt == 0)
                    {
                        BTL_ACTION.SetNULL(ref m_actionParam[0]);
                        storeActionSelectSendData(m_actionParam, 1);
                        seq = (int)SeqselectPokemonUI_Core.SEQ_PROC_QUIT_ROOT;
                        return false;
                    }

                    byte[] puttableList = new byte[PokeParty.MAX_MEMBERS];
                    byte numPuttable = countPuttablePokemons(puttableList);
                    if (numPuttable == 0)
                    {
                        BTL_ACTION.SetChangeDepleteParam(ref m_actionParam[0]);
                        storeActionSelectSendData(m_actionParam, 1);
                        seq = (int)SeqselectPokemonUI_Core.SEQ_PROC_QUIT_ROOT;
                        return false;
                    }

                    byte numSelect = (m_myChangePokeCnt > numPuttable) ? numPuttable : m_myChangePokeCnt;
                    m_mainModule.BtlPosToClientID_and_PosIdx(m_myChangePokePos[0], out byte clientID, out byte posIdx);
                    setupPokeSelParam(numSelect, m_pokeSelParam, m_pokeSelResult);
                    if (bForceChangeMode)
                        m_pokeSelParam.DisablePutPosSequence();

                    m_pokeSelResult.SetCancel(false);
                    if (IsGameTimeOver())
                    {
                        storePokeSelResult_ForceQuit();
                        seq = (int)SeqselectPokemonUI_Core.SEQ_SELECT_END;
                        return false;
                    }

                    m_viewCore.CMD_StartPokeSelect(m_pokeSelParam, posIdx, false, m_pokeSelResult);
                    cmdLimit_Start();
                    seq = (int)SeqselectPokemonUI_Core.SEQ_SELECT_ROOT;
                    return false;
                }

                case SeqselectPokemonUI_Core.SEQ_SELECT_ROOT:
                    if (checkSelactForceQuit(null))
                    {
                        m_viewCore.CMD_ForceQuitPokeSelect();
                        seq = (int)SeqselectPokemonUI_Core.SEQ_TIMELIMIT_OVER;
                        return false;
                    }

                    if (!m_viewCore.CMD_WaitPokeSelect())
                        return false;

                    storePokeSelResult(m_pokeSelResult);
                    seq = (int)SeqselectPokemonUI_Core.SEQ_SELECT_END;
                    return false;

                case SeqselectPokemonUI_Core.SEQ_TIMELIMIT_OVER:
                    if (!m_viewCore.CMD_WaitForceQuitPokeSelect())
                        return false;

                    storePokeSelResult_ForceQuit();
                    seq = (int)SeqselectPokemonUI_Core.SEQ_SELECT_END;
                    return false;

                case SeqselectPokemonUI_Core.SEQ_SELECT_END:
                    cmdLimit_End();
                    seq = (int)SeqselectPokemonUI_Core.SEQ_PROC_QUIT_ROOT;
                    return false;

                case SeqselectPokemonUI_Core.SEQ_PROC_QUIT_ROOT:
                    if (m_mainModule.GetCommMode() == BtlCommMode.BTL_COMM_NONE)
                    {
                        seq = (int)SeqselectPokemonUI_Core.SEQ_PROC_QUIT_END;
                        return false;
                    }

                    m_commWaitInfoOn = true;
                    m_viewCore.CMD_StartCommWait();
                    seq = (int)SeqselectPokemonUI_Core.SEQ_COMM_WAIT;
                    return false;

                case SeqselectPokemonUI_Core.SEQ_COMM_WAIT:
                    if (m_viewCore.CMD_WaitCommWait())
                        seq = (int)SeqselectPokemonUI_Core.SEQ_PROC_QUIT_END;
                    return false;

                case SeqselectPokemonUI_Core.SEQ_PROC_QUIT_END:
                    return true;

                default:
                    return false;
            }
        }
		private bool SubProc_UI_ConfirmIrekae(ref int seq) {
            switch ((SeqSubProc_UI_ConfirmIrekae)seq)
            {
                case SeqSubProc_UI_ConfirmIrekae.SEQ_INIT:
                {
                    byte enemyPutPokeID;
                    unsafe
                    {
                        byte* recvData = null;
                        m_adapter.GetRecvData((void**)&recvData);
                        enemyPutPokeID = *recvData;
                    }

                    if (enemyPutPokeID == PokeID.INVALID)
                    {
                        seq = (int)SeqSubProc_UI_ConfirmIrekae.SEQ_DONT_CHANGE;
                        goto case SeqSubProc_UI_ConfirmIrekae.SEQ_DONT_CHANGE;
                    }

                    BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.IrekaeConfirm);
                    BTLV_STRPARAM.AddArg(m_strParam, (int)BTL_CLIENT_ID.BTL_CLIENT_ENEMY1);
                    BTLV_STRPARAM.AddArg(m_strParam, enemyPutPokeID);
                    BTLV_STRPARAM.SetWait(m_strParam, 0);
                    m_viewCore.CMD_StartMsg(m_strParam);
                    seq = (int)SeqSubProc_UI_ConfirmIrekae.SEQ_START_CONFIRM;
                    return false;
                }

                case SeqSubProc_UI_ConfirmIrekae.SEQ_START_CONFIRM:
                    if (!m_viewCore.CMD_WaitMsg_WithoutHide())
                        return false;

                    m_viewCore.CMD_YESNO_Start(true, YesNoMode.YESNO_MODE_POKE_CHANGE);
                    seq = (int)SeqSubProc_UI_ConfirmIrekae.SEQ_WAIT_CONFIRM;
                    return false;

                case SeqSubProc_UI_ConfirmIrekae.SEQ_WAIT_CONFIRM:
                {
                    if (!m_viewCore.CMD_YESNO_Wait(out BtlYesNo result))
                        return false;

                    m_viewCore.CMD_HideMsg();
                    if (result != BtlYesNo.BTL_YESNO_YES)
                    {
                        seq = (int)SeqSubProc_UI_ConfirmIrekae.SEQ_DONT_CHANGE;
                        goto case SeqSubProc_UI_ConfirmIrekae.SEQ_DONT_CHANGE;
                    }

                    BtlPokePos[] changePos = new BtlPokePos[1];
                    setupPokeSelParam((byte)changePos.Length, m_pokeSelParam, m_pokeSelResult);
                    m_viewCore.CMD_StartPokeSelect(m_pokeSelParam, 0, true, m_pokeSelResult);
                    seq = (int)SeqSubProc_UI_ConfirmIrekae.SEQ_WAIT_POKESELECT;
                    return false;
                }

                case SeqSubProc_UI_ConfirmIrekae.SEQ_WAIT_POKESELECT:
                {
                    if (!m_viewCore.CMD_WaitPokeSelect())
                        return false;

                    if (m_pokeSelResult.IsCancel())
                    {
                        seq = (int)SeqSubProc_UI_ConfirmIrekae.SEQ_DONT_CHANGE;
                        goto case SeqSubProc_UI_ConfirmIrekae.SEQ_DONT_CHANGE;
                    }

                    byte memberIdx = m_pokeSelResult.GetLast();
                    if ((byte)(memberIdx - 1) > 4)
                    {
                        seq = (int)SeqSubProc_UI_ConfirmIrekae.SEQ_DONT_CHANGE;
                        goto case SeqSubProc_UI_ConfirmIrekae.SEQ_DONT_CHANGE;
                    }

                    BTL_ACTION.SetChangeParam(ref m_actionParam[0], 0, memberIdx);
                    seq = (int)SeqSubProc_UI_ConfirmIrekae.SEQ_RETURN;
                    return false;
                }

                case SeqSubProc_UI_ConfirmIrekae.SEQ_DONT_CHANGE:
                    BTL_ACTION.SetNULL(ref m_actionParam[0]);
                    seq = (int)SeqSubProc_UI_ConfirmIrekae.SEQ_RETURN;
                    goto case SeqSubProc_UI_ConfirmIrekae.SEQ_RETURN;

                case SeqSubProc_UI_ConfirmIrekae.SEQ_RETURN:
                    storeActionSelectSendData(m_actionParam, 1);
                    return true;

                default:
                    return false;
            }
        }
		private bool SubProc_UI_RecordData(ref int seq) {
            unsafe
            {
                void* recvData = null;
                uint dataSize = m_adapter.GetRecvData(&recvData);
                if (recvData == null)
                    return false;

                if (m_recData != null)
                    m_recData.Write(recvData, dataSize);

                if (m_cmdCheckServer != null)
                {
                    m_cmdCheckServer.CMDCHECK_RestoreActionData(recvData, dataSize);
                    m_cmdCheckTimingCode = (byte)m_recData.GetTimingCode(recvData);
                }
            }

            return true;
        }
