		private bool SubProc_ExitCommTrainer(ref int seq, bool isRecPlayMode) {
            switch ((SeqSubProc_ExitCommTrainer)seq)
            {
                case SeqSubProc_ExitCommTrainer.SEQ_START:
                {
                    BtlResult result = expandServerResult(out ResultCause resultCause);
                    m_mainModule.NotifyBattleResult(result, resultCause, false);
                    seq = (int)SeqSubProc_ExitCommTrainer.SEQ_SHOWDOWN_MESSAGE_START;
                    return false;
                }

                case SeqSubProc_ExitCommTrainer.SEQ_SHOWDOWN_MESSAGE_START:
                {
                    if ((isRecPlayMode && m_fRecPlayEndTimeOver) || m_fRecPlayEndBufOver)
                        return true;

                    BtlResult result = expandServerResult(out ResultCause resultCause);
                    if (!getVsCommTrainerExitMessage(m_strParam, result, m_mainModule.IsMultiMode()))
                        return true;

                    m_viewCore.CMD_StartMsg(m_strParam);
                    if (result == BtlResult.BTL_RESULT_WIN)
                    {
                        m_viewCore.CMD_PlayWinBGM();
                        seq = (int)SeqSubProc_ExitCommTrainer.SEQ_SHOWDOWN_MESSAGE_WAIT_WIN;
                    }
                    else
                    {
                        m_viewCore.CMD_FadeOutBGM(30);
                        seq = (int)SeqSubProc_ExitCommTrainer.SEQ_SHOWDOWN_MESSAGE_WAIT_LOSE;
                    }
                    return false;
                }

                case SeqSubProc_ExitCommTrainer.SEQ_SHOWDOWN_MESSAGE_WAIT_WIN:
                    return m_viewCore.CMD_WaitMsg();

                case SeqSubProc_ExitCommTrainer.SEQ_SHOWDOWN_MESSAGE_WAIT_LOSE:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    seq = (int)SeqSubProc_ExitCommTrainer.SEQ_LOSE_BGM_FADEOUT_WAIT;
                    return false;

                case SeqSubProc_ExitCommTrainer.SEQ_LOSE_BGM_FADEOUT_WAIT:
                    if (m_viewCore.CMD_CheckFadeOnBGM())
                        return false;

                    m_viewCore.CMD_StopBGM();
                    return true;

                default:
                    return false;
            }
        }
		private global::Dpr.Battle.Logic.BtlResult expandServerResult(out global::Dpr.Battle.Logic.ResultCause resultCause) {
            BTL_RESULT_CONTEXT resultContext;
            unsafe
            {
                BTL_RESULT_CONTEXT* recvData = null;
                m_adapter.GetRecvData((void**)&recvData);
                resultContext = *recvData;
            }

            BtlResult result = (BtlResult)resultContext.resultCode;
            resultCause = resultContext.resultCause;
            if (result == BtlResult.BTL_RESULT_WIN)
            {
                if (!m_mainModule.IsFriendClientID((byte)resultContext.clientID, m_myID))
                    result = BtlResult.BTL_RESULT_LOSE;
            }
            else if (result == BtlResult.BTL_RESULT_LOSE)
            {
                if (!m_mainModule.IsFriendClientID((byte)resultContext.clientID, m_myID))
                    result = BtlResult.BTL_RESULT_WIN;
            }

            return result;
        }
		private bool getVsCommTrainerExitMessage(global::Dpr.Battle.Logic.BTLV_STRPARAM strParam, global::Dpr.Battle.Logic.BtlResult battleResult, bool isMultiMode) {
            byte enemyClientID = m_mainModule.GetEnemyClientID(0);
            ushort strID;
            switch (battleResult)
            {
                case BtlResult.BTL_RESULT_LOSE: strID = BTL_STRID_STD.LoseComm; break;
                case BtlResult.BTL_RESULT_WIN:  strID = BTL_STRID_STD.WinComm;  break;
                case BtlResult.BTL_RESULT_DRAW: strID = BTL_STRID_STD.DrawComm; break;
                default:
                    return false;
            }

            if (isMultiMode)
                strID++;

            BTLV_STRPARAM.Setup(strParam, BtlStrType.BTL_STRTYPE_STD, strID);
            BTLV_STRPARAM.AddArg(strParam, enemyClientID);
            if (isMultiMode)
                BTLV_STRPARAM.AddArg(strParam, m_mainModule.GetEnemyClientID(1));

            return true;
        }
		private bool isEnemyClientDouble() {
            return m_mainModule.GetEnemyClientID(0) != m_mainModule.GetEnemyClientID(1);
        }
