		private void msgWinningTrainerStart() {
            byte enemyClientID1 = m_mainModule.GetEnemyClientID(0);
            byte enemyClientID2 = m_mainModule.GetEnemyClientID(1);
            if (enemyClientID1 == enemyClientID2)
            {
                BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.WinTrainer);
                BTLV_STRPARAM.AddArg(m_strParam, enemyClientID1);
                return;
            }

            Dpr.Trainer.TrainerType tagTrainerType = TrainerSystem.GetTagTrainerType(m_mainModule.GetClientTrainerType(enemyClientID1), m_mainModule.GetClientTrainerType(enemyClientID2));
            if (tagTrainerType == Dpr.Trainer.TrainerType.INVALID)
            {
                BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.WinTrainer2);
                BTLV_STRPARAM.AddArg(m_strParam, enemyClientID1);
                BTLV_STRPARAM.AddArg(m_strParam, enemyClientID2);
            }
            else
            {
                BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.WinTrainer_Tag);
                BTLV_STRPARAM.AddArg(m_strParam, (int)tagTrainerType);
                BTLV_STRPARAM.AddArg(m_strParam, enemyClientID1);
                BTLV_STRPARAM.AddArg(m_strParam, enemyClientID2);
            }
        }
