		private bool SubProc_UI_ExitForNPC(ref int seq) {
            switch ((SeqSubProc_UI_ExitForNPC)seq)
            {
                case SeqSubProc_UI_ExitForNPC.SEQ_INIT:
                {
                    BtlResult result = expandServerResult(out ResultCause resultCause);
                    if (result == BtlResult.BTL_RESULT_WIN)
                    {
                        m_viewCore.CMD_PlayWinBGM();
                        msgWinningTrainerStart();
                        m_viewCore.CMD_StartMsg(m_strParam);
                        seq = (int)SeqSubProc_UI_ExitForNPC.SEQ_WIN_START;
                        return false;
                    }

                    if (m_mainModule.GetSetupStatusFlag(BTL_STATUS_FLAG.BTL_STATUS_FLAG_NO_LOSE))
                        return true;

                    byte playerClientID = m_mainModule.GetPlayerClientID();
                    BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.LoseStart);
                    BTLV_STRPARAM.AddArg(m_strParam, playerClientID);
                    BTLV_STRPARAM.AddArg(m_strParam, playerClientID);
                    m_viewCore.CMD_StartMsg(m_strParam);
                    seq = (int)SeqSubProc_UI_ExitForNPC.SEQ_LOSE_START;
                    return false;
                }

                case SeqSubProc_UI_ExitForNPC.SEQ_WIN_START:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    m_viewCore.CMD_TrainerIn_Lose(BtlvPos.BTL_VPOS_FAR_1);
                    seq = (int)SeqSubProc_UI_ExitForNPC.SEQ_WIN_WAIT_TR1_IN;
                    return false;

                case SeqSubProc_UI_ExitForNPC.SEQ_WIN_WAIT_TR1_IN:
                    if (!m_viewCore.CMD_WaitTrainerIn())
                        return false;

                    m_viewCore.CMD_StartMsgTrainer(m_mainModule.GetEnemyClientID(0), (uint)TrainerMessageID.MESSAGE_LOSE, true);
                    seq = (int)SeqSubProc_UI_ExitForNPC.SEQ_WIN_WAIT_TR1_MSG;
                    return false;

                case SeqSubProc_UI_ExitForNPC.SEQ_WIN_WAIT_TR1_MSG:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    if (isEnemyClientDouble())
                        seq = (int)SeqSubProc_UI_ExitForNPC.SEQ_WIN_WAIT_TR1_OUT;
                    else
                        seq = (int)SeqSubProc_UI_ExitForNPC.SEQ_WIN_GET_MONEY_MSG;
                    return false;

                case SeqSubProc_UI_ExitForNPC.SEQ_WIN_WAIT_TR1_OUT:
                    m_viewCore.CMD_TrainerIn_Lose(BtlvPos.BTL_VPOS_FAR_2);
                    seq = (int)SeqSubProc_UI_ExitForNPC.SEQ_WIN_WAIT_TR2_IN;
                    return false;

                case SeqSubProc_UI_ExitForNPC.SEQ_WIN_WAIT_TR2_IN:
                    if (!m_viewCore.CMD_WaitTrainerIn())
                        return false;

                    m_viewCore.CMD_StartMsgTrainer(m_mainModule.GetEnemyClientID(1), (uint)TrainerMessageID.MESSAGE_LOSE, true);
                    seq = (int)SeqSubProc_UI_ExitForNPC.SEQ_WIN_WAIT_TR2_MSG;
                    return false;

                case SeqSubProc_UI_ExitForNPC.SEQ_WIN_WAIT_TR2_MSG:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    seq = (int)SeqSubProc_UI_ExitForNPC.SEQ_WIN_GET_MONEY_MSG;
                    return false;

                case SeqSubProc_UI_ExitForNPC.SEQ_WIN_GET_MONEY_MSG:
                    if (!m_mainModule.IsMoneySeqEnable())
                        return true;

                    seq = (int)SeqSubProc_UI_ExitForNPC.SEQ_WIN_GET_MONEY;
                    return false;

                case SeqSubProc_UI_ExitForNPC.SEQ_WIN_GET_MONEY:
                {
                    uint money = m_mainModule.FixRegularMoney();
                    if (money != 0)
                    {
                        BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.GetMoney);
                        BTLV_STRPARAM.AddArg(m_strParam, m_mainModule.GetPlayerClientID());
                        BTLV_STRPARAM.AddArg(m_strParam, (int)money);
                        m_viewCore.CMD_StartMsg(m_strParam);
                    }

                    if (m_mainModule.GetBonusMoney() != 0)
                        seq = (int)SeqSubProc_UI_ExitForNPC.SEQ_WIN_BONUS_MONEY;
                    else
                        seq = (int)SeqSubProc_UI_ExitForNPC.SEQ_END;
                    return false;
                }

                case SeqSubProc_UI_ExitForNPC.SEQ_WIN_BONUS_MONEY:
                {
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    uint bonus = m_mainModule.GetBonusMoney();
                    if (bonus != 0)
                    {
                        setBonusMoneyGettingStr(m_strParam, bonus);
                        m_viewCore.CMD_StartMsg(m_strParam);
                    }

                    seq = (int)SeqSubProc_UI_ExitForNPC.SEQ_END;
                    return false;
                }

                case SeqSubProc_UI_ExitForNPC.SEQ_LOSE_START:
                {
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    uint loseMoney = m_mainModule.FixLoseMoney();
                    if (loseMoney != 0)
                    {
                        BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.LoseMoneyTrainer);
                        BTLV_STRPARAM.AddArg(m_strParam, m_myID);
                        BTLV_STRPARAM.AddArg(m_strParam, (int)loseMoney);
                        m_viewCore.CMD_StartMsg(m_strParam);
                    }

                    seq = (int)SeqSubProc_UI_ExitForNPC.SEQ_LOSE_WAIT_MSG1;
                    return false;
                }

                case SeqSubProc_UI_ExitForNPC.SEQ_LOSE_WAIT_MSG1:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.LoseEnd);
                    BTLV_STRPARAM.AddArg(m_strParam, m_myID);
                    m_viewCore.CMD_StartMsg(m_strParam);
                    seq = (int)SeqSubProc_UI_ExitForNPC.SEQ_END;
                    return false;

                case SeqSubProc_UI_ExitForNPC.SEQ_END:
                    return m_viewCore.CMD_WaitMsg();

                default:
                    return true;
            }
        }
