		private bool SubProc_ExitForSubwayTrainer(ref int seq, bool isRecPlayMode) {
            switch ((SeqSubProc_ExitForSubwayTrainer)seq)
            {
                case SeqSubProc_ExitForSubwayTrainer.SEQ_START:
                {
                    BtlResult result = expandServerResult(out ResultCause resultCause);
                    m_mainModule.NotifyBattleResult(result, resultCause, false);
                    seq = (int)SeqSubProc_ExitForSubwayTrainer.SEQ_INIT;
                    return false;
                }

                case SeqSubProc_ExitForSubwayTrainer.SEQ_INIT:
                {
                    if (isRecPlayMode && m_fRecPlayEndTimeOver)
                        return true;

                    BtlResult result = expandServerResult(out ResultCause resultCause);
                    if (result == BtlResult.BTL_RESULT_WIN)
                    {
                        m_viewCore.CMD_PlayWinBGM();
                        m_viewCore.CMD_TrainerIn_Lose(BtlvPos.BTL_VPOS_FAR_1);
                    }
                    else if (result == BtlResult.BTL_RESULT_LOSE)
                    {
                        m_viewCore.CMD_TrainerIn_Win(BtlvPos.BTL_VPOS_FAR_1);
                    }
                    else
                    {
                        return true;
                    }

                    seq = (int)SeqSubProc_ExitForSubwayTrainer.SEQ_WAIT_TRAINER_IN;
                    return false;
                }

                case SeqSubProc_ExitForSubwayTrainer.SEQ_WAIT_TRAINER_IN:
                    if (!m_viewCore.CMD_WaitTrainerIn())
                        return false;

                    m_viewCore.CMD_StartMsgTrainer(m_mainModule.GetEnemyClientID(0), (uint)TrainerMessageID.MESSAGE_LOSE, true);
                    seq = (int)SeqSubProc_ExitForSubwayTrainer.SEQ_WAIT_MSG;
                    return false;

                case SeqSubProc_ExitForSubwayTrainer.SEQ_WAIT_MSG:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    if (!isEnemyClientDouble())
                        return true;

                    seq = (int)SeqSubProc_ExitForSubwayTrainer.SEQ_WAIT_TRAINER_OUT;
                    return false;

                case SeqSubProc_ExitForSubwayTrainer.SEQ_WAIT_TRAINER_OUT:
                {
                    BtlResult result = expandServerResult(out ResultCause resultCause);
                    if (result == BtlResult.BTL_RESULT_WIN)
                        m_viewCore.CMD_TrainerIn_Lose(BtlvPos.BTL_VPOS_FAR_2);
                    else if (result == BtlResult.BTL_RESULT_LOSE)
                        m_viewCore.CMD_TrainerIn_Win(BtlvPos.BTL_VPOS_FAR_2);

                    seq = (int)SeqSubProc_ExitForSubwayTrainer.SEQ_WAIT_TRAINER2_IN;
                    return false;
                }

                case SeqSubProc_ExitForSubwayTrainer.SEQ_WAIT_TRAINER2_IN:
                    if (!m_viewCore.CMD_WaitTrainerIn())
                        return false;

                    m_viewCore.CMD_StartMsgTrainer(m_mainModule.GetEnemyClientID(1), (uint)TrainerMessageID.MESSAGE_LOSE, true);
                    seq = (int)SeqSubProc_ExitForSubwayTrainer.SEQ_WAIT_MSG2;
                    return false;

                case SeqSubProc_ExitForSubwayTrainer.SEQ_WAIT_MSG2:
                    return m_viewCore.CMD_WaitMsg();

                default:
                    return false;
            }
        }
