		private bool SubProc_UI_CaptureWild(ref int seq) {
            switch (seq)
            {
                case 0:
                {
                    var setupParam = new ClientSeq_Capture.SetupParam();
                    setupParam.client = this;
                    setupParam.pokecon = getPokeCon();
                    setupParam.mainModule = m_mainModule;
                    setupParam.viewSystem = m_viewCore;
                    m_seq_Capture.Setup(setupParam);
                    m_seq_Capture.Start();
                    seq++;
                    return false;
                }

                case 1:
                    m_seq_Capture.Update();
                    return m_seq_Capture.IsFinished();

                default:
                    return false;
