        }
		private bool SubProc_UI_NotifyTimeUp(ref int seq) {
            switch (seq)
            {
                case 0:
                    m_viewCore.CMD_InitFinishWaitCameraEffect();
                    break;

                case 1:
                    if (!m_viewCore.CMD_WaitFinishWaitCameraEffect())
                        return false;

                    m_viewCore.CMD_ResetCommWaitInfo();
                    break;

                case 2:
                case 3:
                    break;

                case 4:
                {
                    getTimeUpMessage(out uint strID, out BtlStrType strType);
                    BTLV_STRPARAM.Setup(m_strParam, strType, (ushort)strID);
                    m_viewCore.CMD_StartMsg(m_strParam);
                    break;
                }

                case 5:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    break;

                default:
                    return true;
            }

            seq++;
            return false;
        }
		private void getTimeUpMessage(out uint strID, out global::Dpr.Battle.Logic.BtlStrType strType) {
            if (m_myType == (byte)BtlClientType.BTL_CLIENT_TYPE_RECPLAY)
            {
                if (!m_fRecPlayEndTimeOver && m_mainModule.IsClientLimitTimeExist())
                {
                    getTimeUpMessage_ClientLimitTime(out strID, out strType);
                    return;
                }
            }
            else if (m_gameLimitTime == 0 || !m_gameTimer.IsFinish(GameTimer.TimerType.GAME))
            {
                if (m_mainModule.IsClientLimitTimeExist())
                {
                    getTimeUpMessage_ClientLimitTime(out strID, out strType);
                    return;
                }
            }

            strID = BTL_STRID_STD.BattleTimeOver;
            strType = BtlStrType.BTL_STRTYPE_STD;
        }
		private void getTimeUpMessage_ClientLimitTime(out uint strID, out global::Dpr.Battle.Logic.BtlStrType strType) {
            bool isEnemyTimeOver = false;
            bool isFriendTimeOver = false;
            unsafe
            {
                for (byte clientID = 0; clientID < (byte)BTL_CLIENT_ID.BTL_CLIENT_NUM; clientID++)
                {
                    if (!m_mainModule.IsExistClient(clientID))
                        continue;

                    if (m_syncClientTime.limitTime[clientID] != 0)
                        continue;

                    if (m_mainModule.IsFriendClientID(m_myID, clientID))
                        isFriendTimeOver = true;
                    else
                        isEnemyTimeOver = true;
                }
            }

            if (isEnemyTimeOver && isFriendTimeOver)
                strID = BTL_STRID_STD.BattleTimeOver;
            else if (isFriendTimeOver)
                strID = BTL_STRID_STD.BattleTimeOver_My;
            else
                strID = BTL_STRID_STD.BattleTimeOver_Your;

            strType = BtlStrType.BTL_STRTYPE_STD;
        }
		private bool SubProc_UI_FadeOut(ref int seq) {
            switch (seq)
            {
                case (int)SeqSubProc_UI_FadeOut.SEQ_START:
                    seq = (int)SeqSubProc_UI_FadeOut.SEQ_FADEOUT_START;
                    goto case (int)SeqSubProc_UI_FadeOut.SEQ_FADEOUT_START;

                case (int)SeqSubProc_UI_FadeOut.SEQ_FADEOUT_START:
                    m_viewCore.CMD_StartCleanUp();
                    seq++;
                    return false;

                case (int)SeqSubProc_UI_FadeOut.SEQ_FAIDEOUT_WAIT:
                    if (!m_viewCore.CMD_WaitCleanUp())
                        return false;

                    seq++;
                    return false;

                case (int)SeqSubProc_UI_FadeOut.SEQ_END:
                    return true;

                default:
                    return false;
            }
        }
		private bool SubProc_REC_FadeOut(ref int seq) {
            if (m_viewCore == null)
                return true;

            return SubProc_UI_FadeOut(ref seq);
        }
		public bool isEvolveEnablePokeExsist() {
            byte memberCount = m_myParty.GetMemberCount();
            for (byte i = 0; i < memberCount; i++)
            {
                BTL_POKEPARAM bpp = m_myParty.GetMemberDataConst(i);
                if (m_mainModule.CanEvolveAfterBattle(bpp))
                    return true;
            }

            return false;
        }
		private bool SubProc_UI_SendLastDataAgain(ref int seq) {
            SendData latestData = m_sendDataContainer.GetLatestData();
            if (latestData != null)
            {
                m_returnDataSerialNumber = latestData.GetSerialNumber();
                m_returnDataServerSeq = latestData.GetServerSequence();
                m_returnDataServerRequest = latestData.GetServerRequest();
                unsafe
                {
                    m_returnDataPtr = latestData.GetData();
                }
                m_returnDataSize = latestData.GetDataSize();
            }
            else
            {
                m_returnDataSerialNumber = 0;
                m_returnDataServerSeq = ServerSequence.END;
                m_returnDataServerRequest = ServerRequest.NONE;
                unsafe
                {
                    m_returnDataPtr = null;
                }
                m_returnDataSize = 0;
            }

            return true;
        }
		private bool SubProc_UI_SendClientLimitTime(ref int seq) {
            unsafe
            {
                ClientSendData.CLIENT_LIMIT_TIME* returnData = m_returnData_ClientLimitTime;
                if (m_viewCore != null)
                    returnData->limitTime = (ushort)m_gameTimer.GetTime(GameTimer.TimerType.CLIENT);
                else
                    returnData->limitTime = (ushort)m_mainModule.GetClientLimitTime();

                m_returnDataSerialNumber = 0;
                m_returnDataServerSeq = ServerSequence.END;
                m_returnDataServerRequest = ServerRequest.NONE;
                m_returnDataPtr = m_returnData_ClientLimitTime;
                m_returnDataSize = (uint)sizeof(ClientSendData.CLIENT_LIMIT_TIME);
            }

            return true;
        }
		private bool SubProc_UI_SyncClientLimitTime(ref int seq) {
            unsafe
            {
                var prevLimitTime = new ServerSendData.CLIENT_LIMIT_TIME();
                ServerSendData.CLIENT_LIMIT_TIME_Copy(ref prevLimitTime, m_syncClientTime);

                ServerSendData.CLIENT_LIMIT_TIME* syncData = null;
                m_adapter.GetRecvData((void**)&syncData);

                for (byte clientID = 0; clientID < (byte)BTL_CLIENT_ID.BTL_CLIENT_NUM; clientID++)
                {
                    if (m_mainModule.IsExistClient(clientID))
                    {
                        // Empty in the shipped binary (the calls remain, 01f5c688..01f5c6d8).
                    }
                }

                if (m_cmdCheckServer != null)
                    m_cmdCheckServer.CMDCHECK_RestoreClientLimitTime(*syncData);

                ServerSendData.CLIENT_LIMIT_TIME_Copy(ref m_syncClientTime, *syncData);

                uint myTime = m_gameTimer.GetTime(GameTimer.TimerType.CLIENT);
                bool isError = m_syncClientTime.limitTime[m_myID] != (ushort)myTime;
                for (byte clientID = 0; clientID < (byte)BTL_CLIENT_ID.BTL_CLIENT_NUM; clientID++)
                {
                    if (m_mainModule.IsExistClient(clientID) && clientID != m_myID)
                    {
                        if (prevLimitTime.limitTime[clientID] < m_syncClientTime.limitTime[clientID])
                            isError = true;
                    }
                }

                if (isError)
                {
                    m_mainModule.NotifyCmdCheckError();
                    m_fCmdCheckEnable = false;
                }
            }

            return true;
        }
		private bool SubProc_UI_RaidBossCapture_Start(ref int seq) {
            switch (seq)
            {
                case 0:
                    m_mainModule.NotifyRaidCaptureStart();
                    m_viewCore.CMD_Raid_StartCoopCapture(BtlPokePos.POS_RAID_BOSS, getRaidBossCaptureStartSeqNo());
                    seq++;
                    return false;

                case 1:
                    if (!m_viewCore.CMD_Raid_StartCoopCapture_Wait())
                        return false;

                    if (m_mainModule.GetRaidBattleParam().bossCaptureDifficulty != RaidBossCaptureDifficulty.IMPOSSIBLE)
                        return true;

                    seq++;
                    return false;

                case 2:
                {
                    BtlvPos vpos = m_mainModule.BtlPosToViewPos(BtlPokePos.POS_RAID_BOSS);
                    m_viewCore.CMD_AddEffectByPos(vpos, BtlEff.BTLEFF_RAIDBOSS_DOWN);
                    seq++;
                    return false;
                }

                case 3:
                    return m_viewCore.CMD_WaitEffectByPos();

                default:
                    return true;
            }
        }
		private uint getRaidBossCaptureStartSeqNo() {
            return m_mainModule.GetRaidBattleParam().bossCaptureDifficulty == RaidBossCaptureDifficulty.IMPOSSIBLE ? 231u : 192u;
        }
		private bool SubProc_UI_RaidBossCapture_SelectBall(ref int seq) {
            switch (seq)
            {
                case (int)SeqSubProc_UI_RaidBossCapture_SelectBall.SEQ_START:
                    seq = (int)SeqSubProc_UI_RaidBossCapture_SelectBall.SEQ_SELECTBALL_START;
                    return false;

                case (int)SeqSubProc_UI_RaidBossCapture_SelectBall.SEQ_SELECTBALL_START:
                {
                    var param = new BattleViewBase.Raid_SelectBall_Param();
                    m_viewCore.CMD_Raid_SelectBall(param);
                    seq = (int)SeqSubProc_UI_RaidBossCapture_SelectBall.SEQ_SELECTBALL_WAIT;
                    return false;
                }

                case (int)SeqSubProc_UI_RaidBossCapture_SelectBall.SEQ_SELECTBALL_WAIT:
                {
                    var result = new BattleViewBase.Raid_SelectBall_Result();
                    if (!m_viewCore.CMD_Raid_SelectBall_Wait(result))
                        return false;

                    unsafe
                    {
                        m_returnData_RaidBallSelect->isThrow = result.isThrow;
                        m_returnData_RaidBallSelect->itemID = (ushort)result.itemno;
                        m_returnDataPtr = m_returnData_RaidBallSelect;
                        m_returnDataSize = (uint)sizeof(ClientSendData.RAID_BALL_SELECT);
                    }

                    if (result.isThrow)
                        registerLastSelectedBall((uint)result.itemno);

                    seq = (int)SeqSubProc_UI_RaidBossCapture_SelectBall.SEQ_END;
                    return false;
                }

                default:
                    return true;
            }
        }
		private bool SubProc_UI_RaidBossCapture_Result(ref int seq) {
            unsafe
            {
                switch (seq)
                {
                    case (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_START:
                    {
                        ServerSendData.RAIDBOSS_CAPTURE_RESULT* recvData = null;
                        m_adapter.GetRecvData((void**)&recvData);
                        ServerSendData.RAIDBOSS_CAPTURE_RESULT_Copy(ref m_raidBossCaptureResult, *recvData);
                        seq = m_raidBossCaptureResult.isThrow[m_myID]
                            ? (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_BALLTHROW_START
                            : (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_ESCAPE;
                        if (m_raidBossCaptureResult.isThrow[m_myID])
                            m_mainModule.DecrementPlayerItem(m_myID, m_raidBossCaptureResult.itemno[m_myID]);

                        return false;
                    }

                    case (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_BALLTHROW_START:
                    {
                        var param = new BattleViewBase.RaidCaptureParam();
                        param.itemno = (ItemNo)m_raidBossCaptureResult.itemno[m_myID];
                        param.isCaptured = m_raidBossCaptureResult.isCaptured[m_myID];
                        param.yureCount = m_raidBossCaptureResult.yureCount[m_myID];
                        m_viewCore.CMD_Raid_Capture(param);
                        seq = (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_BALLTHROW_WAIT;
                        return false;
                    }

                    case (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_BALLTHROW_WAIT:
                        if (!m_viewCore.CMD_Raid_Capture_Wait())
                            return false;

                        seq = m_raidBossCaptureResult.isCaptured[m_myID]
                            ? (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_CAPTURED
                            : (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_ESCAPE;
                        return false;

                    case (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_CAPTURED:
                    {
                        m_mainModule.NotifyBattleResult(BtlResult.BTL_RESULT_CAPTURE, ResultCause.RESULT_CAUSE_OTHER, false);
                        var captureInfo = new CaptureInfo();
                        captureInfo.SetCapturedPokePos(BtlPokePos.POS_RAID_BOSS);
                        captureInfo.SetCapturedClientID((BTL_CLIENT_ID)m_myID);
                        m_mainModule.NotifyCapturedInfo(captureInfo);
                        seq = (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_END;
                        return false;
                    }

                    case (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_ESCAPE:
                        m_mainModule.NotifyBattleResult(BtlResult.BTL_RESULT_WIN, ResultCause.RESULT_CAUSE_ALL_DEAD, false);
                        seq = (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_ESCAPE_ACT_START;
                        return false;

                    case (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_ESCAPE_ACT_START:
                    {
                        BtlvPos vpos = m_mainModule.BtlPosToViewPos(BtlPokePos.POS_RAID_BOSS);
                        m_viewCore.CMD_AddEffectByPos(vpos, BtlEff.BTLEFF_RAIDBOSS_DOWN);
                        seq = (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_ESCAPE_ACT_WAIT;
                        return false;
                    }

                    case (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_ESCAPE_ACT_WAIT:
                        if (!m_viewCore.CMD_WaitEffectByPos())
                            return false;

                        seq = (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_END;
                        return false;

                    case (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_JOKER_BALLTHROW_START:
                    {
                        var param = new BattleViewBase.RaidCaptureParam();
                        param.itemno = (ItemNo)m_raidBossCaptureResult.itemno[m_myID];
                        param.isCaptured = m_raidBossCaptureResult.isCaptured[m_myID];
                        param.yureCount = m_raidBossCaptureResult.yureCount[m_myID];
                        m_viewCore.CMD_Raid_Capture_vsJoker(param);
                        seq = (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_JOKER_BALLTHROW_WAIT;
                        return false;
                    }

                    case (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_JOKER_BALLTHROW_WAIT:
                        if (!m_viewCore.CMD_Raid_Capture_vsJoker_Wait())
                            return false;

                        seq = (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_CAPTURED;
                        return false;

                    case (int)SeqSubProc_UI_RaidBossCapture_Result.SEQ_END:
                        if (m_raidBossCaptureResult.isCaptured[m_myID])
                        {
                            BTL_POKEPARAM bpp = getPokeCon().GetFrontPokeDataConst(BtlPokePos.POS_RAID_BOSS);
                            if (bpp.IsSpecialG())
                                m_mainModule.RegisterZukanSpGGetFlag(bpp);
                        }
                        return true;

                    default:
                        return true;
                }
            }
        }
		private bool SubProc_UI_LoseRaid(ref int seq) {
            switch (seq)
            {
                case (int)SeqSubProc_UI_LoseRaid.SEQ_START:
                    seq = (int)SeqSubProc_UI_LoseRaid.SEQ_EFFECT_START;
                    return false;

                case (int)SeqSubProc_UI_LoseRaid.SEQ_EFFECT_START:
                    m_viewCore.CMD_Raid_Lose();
                    seq++;
                    return false;

                case (int)SeqSubProc_UI_LoseRaid.SEQ_EFFECT_WAIT:
                    if (!m_viewCore.CMD_Raid_Lose_Wait())
                        return false;

                    seq++;
                    return false;

                case (int)SeqSubProc_UI_LoseRaid.SEQ_END:
                    m_mainModule.NotifyBattleResult(BtlResult.BTL_RESULT_LOSE, ResultCause.RESULT_CAUSE_ALL_DEAD, false);
                    return true;

                default:
                    return true;
            }
        }
