		private bool SubProc_UI_ServerCmd(ref int seq) {
            while (true)
            {
                switch (seq)
                {
                    case 0:
                        m_adapter.ClearTrainerActionRequest();
                        unsafe
                        {
                            void* recvedCmd = null;
                            uint recvedCmdSize = m_adapter.GetRecvData(&recvedCmd);
                            if (m_cmdCheckServer != null && m_cmdCheckTimingCode != 0 && m_fCmdCheckEnable)
                            {
                                if (m_cmdCheckServer.CMDCHECK_Make((rec.Timing)m_cmdCheckTimingCode, recvedCmd, recvedCmdSize))
                                {
                                    m_mainModule.NotifyCmdCheckError();
                                    m_fCmdCheckEnable = false;
                                }
                                m_cmdCheckTimingCode = 0;
                            }

                            m_serverCmdQueue.Copy(recvedCmd, (ushort)recvedCmdSize);
                        }

                        if (m_commWaitInfoOn)
                        {
                            m_commWaitInfoOn = false;
                            m_viewCore.CMD_ResetCommWaitInfo();
                        }

                        m_viewCore.CMD_InitFinishWaitCameraEffect();
                        seq = 1;
                        goto case 1;

                    case 1:
                        if (!m_viewCore.CMD_WaitFinishWaitCameraEffect())
                            return false;

                        seq = 2;
                        goto case 2;

                    case 2:
                        if (m_serverCmdQueue.IsReadFinished())
                        {
                            seq = 5;
                            return true;
                        }

                        if (m_recPlayer.fFadeOutDone)
                            return true;

                        seq = 3;
                        goto case 3;

                    case 3:
                        m_serverCmd = m_serverCmdQueue.Read(m_cmdArgs, (uint)m_cmdArgs.Length);
                        if (m_serverCmd == ServerCommand.NUM)
                            return true;

                        m_scProc = dispatchServerCmdProc(m_serverCmd);
                        m_scSeq = 0;
                        if (m_scProc == null)
                        {
                            seq = 2;
                            break;
                        }

                        seq = 4;
                        goto case 4;

                    case 4:
                        if (!m_scProc(ref m_scSeq, m_cmdArgs))
                            return false;

                        seq = 2;
                        break;

                    default:
                        return true;
                }
            }
        }
		private bool SubProc_AI_ServerCmd(ref int seq) {
            return true;
        }
		private void storeWazaEffectSyncDamageParams(global::Dpr.Battle.Logic.BTL_CLIENT.WAZAEFF_SYNCDAMAGE_CMD_WORK work, global::Dpr.Battle.Logic.ServerCommand[] pTargetCmdList) {
            uint readStateSave = m_serverCmdQueue.PushReadState();
            uint cmdCount = 0;
            uint exArgsPos = ServerCommandQueue.QUE_READING_STATE_NULL;
            while (!m_serverCmdQueue.IsReadFinished())
            {
                uint cmdPos = m_serverCmdQueue.PushReadState();
                ServerCommand cmd = m_serverCmdQueue.Read(work.store[cmdCount].cmdArgs, (uint)work.store[cmdCount].cmdArgs.Length);
                if (exArgsPos == ServerCommandQueue.QUE_READING_STATE_NULL)
                    work.store[cmdCount].variableArgs.Clear();

                if (cmd == ServerCommand._EX_VALIABLE_ARGS)
                {
                    work.store[cmdCount].variableArgs.Setup(work.store[cmdCount].cmdArgs);
                    exArgsPos = cmdPos;
                    continue;
                }

                if (cmd == ServerCommand.ACT_WAZA_EFFECT || cmd == ServerCommand.NUM)
                    break;

                if (cmd == ServerCommand._EX_WAZAEFF_SYNC_CHAPTER)
                {
                    m_serverCmdQueue.ReplaceWithSkipCmd(cmdPos);
                    break;
                }

                if (tables.IsInclude(cmd, pTargetCmdList))
                {
                    if (exArgsPos != ServerCommandQueue.QUE_READING_STATE_NULL)
                        m_serverCmdQueue.ReplaceWithSkipCmd(exArgsPos);

                    m_serverCmdQueue.ReplaceWithSkipCmd(cmdPos);
                    work.store[cmdCount].cmdProc = dispatchServerCmdProc(cmd);
                    work.store[cmdCount].cmd = cmd;
                    work.store[cmdCount].bDone = false;
                    work.store[cmdCount].seq = 0;
                    cmdCount++;
                }

                if (cmdCount >= work.store.Length)
                    break;

                exArgsPos = ServerCommandQueue.QUE_READING_STATE_NULL;
            }

            work.cmdCount = cmdCount;
            m_serverCmdQueue.PopReadState(readStateSave);
        }
		private bool putWazaEffSyncDamage(global::Dpr.Battle.Logic.BTL_CLIENT.WAZAEFF_SYNCDAMAGE_CMD_WORK work) {
            bool isAllDone = true;
            for (uint i = 0; i < work.cmdCount; i++)
            {
                if (work.store[i].bDone)
                    continue;

                VariableArgs oldArgs = null;
                if (work.store[i].variableArgs.GetCount() != 0)
                    oldArgs = PushTmpVariableArgsWork(work.store[i].variableArgs);

                work.store[i].bDone = work.store[i].cmdProc(ref work.store[i].seq, work.store[i].cmdArgs);

                if (work.store[i].variableArgs.GetCount() != 0)
                    PopTmpVariableArgsWork(oldArgs);

                isAllDone &= work.store[i].bDone;
            }

            return isAllDone;
        }
		private bool scProc_ACT_MemberOutMsg(ref int seq, int[] args) {
            switch (seq)
            {
                case 0:
                {
                    ushort strID = checkMemberOutStrID((byte)args[0], (byte)args[1], out bool fClientArg);
                    BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, strID);
                    if (fClientArg)
                        BTLV_STRPARAM.AddArg(m_strParam, args[0]);

                    BTLV_STRPARAM.AddArg(m_strParam, args[1]);
                    m_viewCore.CMD_StartMsg(m_strParam);
                    seq++;
                    return false;
                }

                case 1:
                    return m_viewCore.CMD_WaitMsg();

                default:
                    return false;
            }
        }
		private ushort checkMemberOutStrID(byte clientID, byte pokeID, out bool fClientArg) {
            if (clientID != m_myID)
            {
                fClientArg = true;
                return m_mainModule.IsClientNPC(clientID) ? (ushort)BTL_STRID_STD.BackChange_NPC : (ushort)BTL_STRID_STD.BackChange_Player;
            }

            fClientArg = false;
            BTL_POKEPARAM bpp = getPokeCon().GetPokeParam(pokeID);
            if (m_mainModule.GetPokeFriendship(bpp) >= 220)
                return BTL_STRID_STD.FR_ChangeBack;

            if (m_mainModule.GetRule() != BtlRule.BTL_RULE_SINGLE)
                return BTL_STRID_STD.BackChange2;

            if (m_mainModule.GetCommMode() != BtlCommMode.BTL_COMM_NONE)
                return BTL_STRID_STD.BackChange2;

            uint ratio = enemyPokeHPBase_CheckRatio();
            if (ratio >= 75)
                return BTL_STRID_STD.BackChange5;

            if (ratio > 50)
                return BTL_STRID_STD.BackChange4;

            if (ratio > 25)
                return BTL_STRID_STD.BackChange3;

            if (ratio != 0)
                return BTL_STRID_STD.BackChange2;

            return BTL_STRID_STD.BackChange1;
        }
		private bool scProc_ACT_MemberOut(ref int seq, int[] args) {
            switch (seq)
            {
                case 0:
                {
                    BtlvPos vpos = m_mainModule.BtlPosToViewPos((BtlPokePos)args[0]);
                    m_viewCore.CMD_ACT_MemberOut_Start(vpos, (BtlEff)args[1]);
                    seq++;
                    return false;
                }

                case 1:
                    return m_viewCore.CMD_ACT_MemberOut_Wait();

                default:
                    return false;
            }
        }
		private bool scProc_ACT_MemberIn(ref int seq, int[] args) {
            byte clientID = (byte)args[0];
            byte posIdx = (byte)args[1];
            bool fPutMsg = (byte)args[3] != 0;
            switch (seq)
            {
                case (int)SeqscProc_ACT_MemberIn.SEQ_TRAINER_MSG_SWITCH:
                    if (m_mainModule.IsCompetitorScenarioMode() && IsTrainerMessageEnable_OnLastPokeIn(clientID))
                        seq = (int)SeqscProc_ACT_MemberIn.SEQ_TRAINER_MSG_START;
                    else
                        seq = (int)SeqscProc_ACT_MemberIn.SEQ_MEMBERIN_MSG_START;
                    return false;

                case (int)SeqscProc_ACT_MemberIn.SEQ_TRAINER_MSG_START:
                    StartTrainerMessage(clientID, TrainerMessageID.MESSAGE_LAST_POKE_IN);
                    seq++;
                    return false;

                case (int)SeqscProc_ACT_MemberIn.SEQ_TRAINER_MSG_WAIT:
                    if (UpdateTrainerMessage())
                        seq++;
                    return false;

                case (int)SeqscProc_ACT_MemberIn.SEQ_MEMBERIN_MSG_START:
                {
                    if (!fPutMsg)
                    {
                        seq = (int)SeqscProc_ACT_MemberIn.SEQ_MEMBERIN_MSG_WAIT;
                        return false;
                    }

                    BTL_POKEPARAM bpp = getPokeCon().GetClientPokeDataConst(clientID, posIdx);
                    byte pokeID = bpp.GetID();
                    if (m_mainModule.IsOpponentClientID(m_myID, clientID))
                    {
                        if (m_mainModule.IsClientNPC(clientID))
                            BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.PutSingle_NPC);
                        else
                            BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.PutSingle_Player);

                        BTLV_STRPARAM.AddArg(m_strParam, clientID);
                        BTLV_STRPARAM.AddArg(m_strParam, pokeID);
                    }
                    else if (m_myID == clientID)
                    {
                        ushort strID = checkMemberPutStrID(bpp);
                        BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, strID);
                        BTLV_STRPARAM.AddArg(m_strParam, pokeID);
                    }
                    else
                    {
                        BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.PutSingle_Player);
                        BTLV_STRPARAM.AddArg(m_strParam, clientID);
                        BTLV_STRPARAM.AddArg(m_strParam, pokeID);
                    }

                    m_viewCore.CMD_StartMsg(m_strParam);
                    seq++;
                    return false;
                }

                case (int)SeqscProc_ACT_MemberIn.SEQ_MEMBERIN_MSG_WAIT:
                {
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    BtlPokePos pos = m_mainModule.GetClientPokePos(clientID, posIdx);
                    m_viewCore.CMD_StartMemberChangeAct(pos, clientID, posIdx);
                    seq++;
                    return false;
                }

                case (int)SeqscProc_ACT_MemberIn.SEQ_MEMBERIN_ACT:
                    if (!m_viewCore.CMD_WaitMemberChangeAct())
                        return false;

                    enemyPokeHPBase_Update();
                    return true;

                default:
                    return false;
            }
        }
		private bool IsTrainerMessageEnable_OnLastPokeIn(byte clientID) {
            if (!m_mainModule.IsClientTrainerExist(clientID))
                return false;

            if (getPokeCon().GetPartyDataConst(clientID).GetAliveMemberCount() != 1)
                return false;

            return m_trainerMessageManager.IsMessageExist(clientID, TrainerMessageID.MESSAGE_LAST_POKE_IN);
        }
		private void StartTrainerMessage(byte clientID, global::Dpr.Battle.Logic.TrainerMessageID messageID) {
            var setupParam = new ClientSeq_TrainerMessage.SetupParam();
            setupParam.pMainModule = m_mainModule;
            setupParam.pViewSystem = m_viewCore;
            setupParam.pMessageManager = m_trainerMessageManager;
            m_seq_TrainerMessage.Setup(setupParam);
            m_seq_TrainerMessage.Start(clientID, messageID);
        }
		private bool UpdateTrainerMessage() {
            m_seq_TrainerMessage.Update();
            return m_seq_TrainerMessage.IsFinished();
        }
		private ushort checkMemberPutStrID(global::Dpr.Battle.Logic.BTL_POKEPARAM putPoke) {
            byte opponentClientID = (byte)m_mainModule.GetOpponentClientID(m_myID, 0);
            BTL_POKEPARAM opponentPoke = getPokeCon().GetClientPokeDataConst(opponentClientID, 0);
            return getMemberPutStrID(putPoke, opponentPoke);
        }
		private ushort getMemberPutStrID(global::Dpr.Battle.Logic.BTL_POKEPARAM putPoke, global::Dpr.Battle.Logic.BTL_POKEPARAM opponentPoke) {
            if (m_mainModule.GetRule() == BtlRule.BTL_RULE_SINGLE && !opponentPoke.IsDead())
            {
                int hpRatio = opponentPoke.GetHPRatio();
                if (hpRatio < FX32.CONST_77_5)
                {
                    if (hpRatio >= FX32.CONST_55_0)
                        return BTL_STRID_STD.PutChange1;

                    if (hpRatio >= FX32.CONST_32_5)
                        return BTL_STRID_STD.PutChange2;

                    if (hpRatio >= FX32.CONST_10_0)
                        return BTL_STRID_STD.PutChange3;

                    return BTL_STRID_STD.PutChange4;
                }
            }

            if (m_mainModule.GetPokeFriendship(putPoke) >= 220)
                return BTL_STRID_STD.FR_PutPoke;

            return BTL_STRID_STD.PutSingle;
        }
		private bool scProc_MSG_Std(ref int seq, int[] args) {
            if (IsChapterSkipMode())
                return true;

            unsafe
            {
                fixed (int* pArgs = args)
                {
                    return scproc_msgStdCore(ref seq, (ushort)args[0], pArgs + 1, args.Length - 1);
                }
            }
        }
		private bool scProc_MSG_StdSE(ref int seq, int[] args) {
            if (IsChapterSkipMode())
                return true;

            switch (seq)
            {
                case 0:
                    scProc_MSG_StdSE_subSeq = 0;
                    seq++;
                    goto case 1;

                case 1:
                    unsafe
                    {
                        fixed (int* pArgs = args)
                        {
                            if (scproc_msgStdCore(ref scProc_MSG_StdSE_subSeq, (ushort)args[0], pArgs + 2, args.Length - 2))
                            {
                                m_viewCore.CMD_PlaySE((SoundType)args[1]);
                                seq++;
                            }
                        }
                    }
                    return false;

                case 2:
                    return m_viewCore.CMD_IsSEFinished((SoundType)args[1]);

                default:
                    return false;
            }
        }
		private unsafe bool scproc_msgStdCore(ref int seq, ushort strID, int* args, int argsLen) {
            if (IsChapterSkipMode())
                return true;

            switch (seq)
