		private bool scProc_ACT_WazaEffect(ref int seq, int[] args) {
            if (IsChapterSkipMode())
                return true;

            ServerCommand[] syncDamageCmdList = new ServerCommand[]
            {
                ServerCommand.OP_HP_MINUS_SYNC_WAZAEFF,
                ServerCommand.ACT_WAZA_DMG,
                ServerCommand.ACT_WAZA_DMG_PLURAL,
                ServerCommand.ACT_MIGAWARI_DAMAGE,
                ServerCommand.OP_GWALL_GAUGE_SUB,
                ServerCommand.OP_GWALL_GAUGE_ADD,
            };
            ServerCommand[] notViewSyncCmdList = new ServerCommand[2];
            notViewSyncCmdList[0] = ServerCommand.OP_GWALL_GAUGE_SUB;
            notViewSyncCmdList[1] = ServerCommand.OP_GWALL_GAUGE_ADD;

            switch (seq)
            {
                case 0:
                    switch (scproc_wazaEffProc_Start(args))
                    {
                        case WazaEffectCmdProcResult.WAZAEFF_CMD_RESULT_PROC_SYNC:
                            m_bWazaEffectDone = false;
                            m_bSyncEffectDone = false;
                            storeWazaEffectSyncDamageParams(m_wazaEffDmgSyncWork, syncDamageCmdList);
                            seq = 2;
                            break;

                        case WazaEffectCmdProcResult.WAZAEFF_CMD_RESULT_PROC_NO_SYNC:
                            seq = 1;
                            break;

                        default:
                            m_viewCore.CMD_ACT_WazaEffect_NotView((WazaNo)args[2]);
                            m_bWazaEffectDone = true;
                            m_bSyncEffectDone = false;
                            storeWazaEffectSyncDamageParams(m_wazaEffDmgSyncWork, notViewSyncCmdList);
                            seq = 2;
                            break;
                    }
                    return false;

                case 1:
                    return m_viewCore.CMD_ACT_WazaEffect_Wait();

                case 2:
                    if (!m_bWazaEffectDone)
                        m_bWazaEffectDone = m_viewCore.CMD_ACT_WazaEffect_Wait();

                    if (!m_bSyncEffectDone)
                        m_bSyncEffectDone = putWazaEffSyncDamage(m_wazaEffDmgSyncWork);

                    return m_bWazaEffectDone && m_bSyncEffectDone;

                default:
                    return false;
            }
        }
		private global::Dpr.Battle.Logic.BTL_CLIENT.WazaEffectCmdProcResult scproc_wazaEffProc_Start(int[] args) {
            BtlPokePos atPokePos = (BtlPokePos)args[0];
            BtlPokePos defPokePos = (BtlPokePos)args[1];
            WazaNo waza = (WazaNo)args[2];
            byte wazaType = (byte)args[3];

            BTL_POKEPARAM attacker = getPokeCon().GetFrontPokeDataConst(atPokePos);
            if (m_mainModule.IsPlayerSide(m_mainModule.PosToSide(atPokePos)))
                m_mainModule.SetTvNaviData_UseWaza(attacker, (ushort)waza);

            if (!m_mainModule.IsWazaEffectEnable())
                return WazaEffectCmdProcResult.WAZAEFF_CMD_RESULT_NO_PROC;

            if (!m_pBattleEnv.GetPosPoke().IsExist(attacker.GetID()))
                return WazaEffectCmdProcResult.WAZAEFF_CMD_RESULT_NO_PROC;

            BtlvWazaEffect_TurnType turnType = (BtlvWazaEffect_TurnType)args[4];
            byte continueCount = (byte)args[5];
            bool syncDamageEffect = args[6] != 0;
            bool isGShockOccur = args[7] != 0;

            WazaTarget wazaRange = checkWazaRange(waza, atPokePos);
            if (wazaEff_IsOmitFriendAttackEffect(waza, wazaRange, atPokePos, defPokePos))
                return WazaEffectCmdProcResult.WAZAEFF_CMD_RESULT_NO_PROC;

            m_viewCore.CMD_ACT_WazaEffect_Start(atPokePos, defPokePos, waza, wazaType, wazaRange, turnType, continueCount, syncDamageEffect, isGShockOccur);
            return syncDamageEffect ? WazaEffectCmdProcResult.WAZAEFF_CMD_RESULT_PROC_SYNC : WazaEffectCmdProcResult.WAZAEFF_CMD_RESULT_PROC_NO_SYNC;
        }
		private bool wazaEff_IsOmitFriendAttackEffect(global::Pml.WazaNo waza, global::Pml.WazaData.WazaTarget wazaRange, global::Dpr.Battle.Logic.BtlPokePos atkPokePos, global::Dpr.Battle.Logic.BtlPokePos defPokePos) {
            if (defPokePos == BtlPokePos.POS_NULL)
                return false;

            if (m_mainModule.IsFriendPokePos(atkPokePos, defPokePos) && wazaRange == WazaTarget.TARGET_OTHER_SELECT)
                return !WAZADATA.GetFlag(waza, WazaFlag.EFFECT_TO_FRIEND);

            return false;
        }
		private global::Pml.WazaData.WazaTarget checkWazaRange(global::Pml.WazaNo waza, global::Dpr.Battle.Logic.BtlPokePos atPokePos) {
            BTL_POKEPARAM attacker = getPokeCon().GetFrontPokeDataConst(atPokePos);
            return calc.GetWazaTarget(waza, attacker);
        }
