		private void setupRaidRewardParam(global::Dpr.Battle.Logic.BattleViewBase.RaidRewardParam pRewardParam) {
            RaidBattleParam raidParam = m_mainModule.GetRaidBattleParam();
            for (uint i = 0; i < BattleDefConst.RAID_REWARD_ITEM_MAX; i++)
            {
                RaidRewardItemData reward = raidParam.rewards[i];
                ItemNo itemno = reward.itemno;
                uint amount = reward.amount;
                pRewardParam.SetItem(i, itemno, amount);
            }

            pRewardParam.pBPP = getPokeCon().GetFrontPokeDataConst(BtlPokePos.POS_RAID_BOSS);
            pRewardParam.rank = pRewardParam.pBPP.GetRaidBossParam().GetGrade();
            unsafe
            {
                pRewardParam.bCaptured = m_raidBossCaptureResult.isCaptured[m_myID];
            }
            pRewardParam.bRare = m_mainModule.IsRaidBossRare();
        }
