		private bool scProc_ACTOP_WeatherStart(ref int seq, int[] args) {
            BtlWeather weather = (BtlWeather)args[0];
            ChangeWeatherCause cause = (ChangeWeatherCause)args[4];
            switch (seq)
            {
                case 0:
                    getServerCmdExecutor().StartWeather(weather, (byte)args[1], (byte)args[2], (byte)args[3]);
                    if (!needWeatherStartEffect(cause))
                    {
                        seq = 2;
                        return false;
                    }

                    if (weather < BtlWeather.BTL_WEATHER_MAX)
                        m_viewCore.CMD_ChangeWheather(weather);

                    seq++;
                    return false;

                case 1:
                    if (m_viewCore.CMD_ChangeWheather_Wait())
                        seq++;
                    return false;

                case 2:
                {
                    if (IsChapterSkipMode())
                        return true;

                    int strID = getWeatherStartMessage(weather, cause);
                    if (strID < 0)
                        return true;

                    m_viewCore.CMD_StartMsgStd((ushort)strID, null);
                    seq++;
                    return false;
                }

                case 3:
                    return m_viewCore.CMD_WaitMsg();

                default:
                    return false;
            }
        }
		private bool needWeatherStartEffect(global::Dpr.Battle.Logic.ChangeWeatherCause cause) {
            return cause != ChangeWeatherCause.ON_BATTLE_START;
        }
		private int getWeatherStartMessage(global::Dpr.Battle.Logic.BtlWeather weather, global::Dpr.Battle.Logic.ChangeWeatherCause cause) {
            for (byte i = 0; i < getWeatherStartMessageParamTable.Length; i++)
            {
                if (getWeatherStartMessageParamTable[i].weather == weather)
                {
                    // The shipped code indexes the table by the weather value, not by the matching index.
                    if (cause == ChangeWeatherCause.ON_BATTLE_START)
                        return getWeatherStartMessageParamTable[(int)weather].strID_onBattleStart;

                    return getWeatherStartMessageParamTable[(int)weather].strID_others;
                }
            }

            return -1;
        }
		private bool scProc_ACT_WeatherEnd(ref int seq, int[] args) {
            switch (seq)
            {
                case 0:
                {
                    ushort strID;
                    switch ((BtlWeather)args[0])
                    {
                        case BtlWeather.BTL_WEATHER_SHINE: strID = BTL_STRID_STD.ShineEnd; break;
                        case BtlWeather.BTL_WEATHER_RAIN: strID = BTL_STRID_STD.RainEnd; break;
                        case BtlWeather.BTL_WEATHER_SNOW: strID = BTL_STRID_STD.SnowEnd; break;
                        case BtlWeather.BTL_WEATHER_SAND: strID = BTL_STRID_STD.StormEnd; break;
                        case BtlWeather.BTL_WEATHER_STORM: strID = BTL_STRID_STD.RainStormEnd; break;
                        case BtlWeather.BTL_WEATHER_DAY: strID = BTL_STRID_STD.DayEnd; break;
                        case BtlWeather.BTL_WEATHER_TURBULENCE: strID = BTL_STRID_STD.TurbulenceEnd; break;
                        default: return true;
                    }

                    m_viewCore.CMD_StartMsgStd(strID, null);
                    seq++;
                    return false;
                }

                case 1:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    m_viewCore.CMD_ChangeWheather(BtlWeather.BTL_WEATHER_NONE);
                    seq++;
                    return false;

                case 2:
                    return m_viewCore.CMD_ChangeWheather_Wait();

                default:
                    return false;
            }
        }
