		private bool scProc_ACT_FriendshipEffectMsg(ref int seq, int[] args) {
            if (IsChapterSkipMode())
                return true;

            if (seq == 0)
            {
                scProc_ACT_FriendshipEffectMsg_effSeq = 0;
                scProc_ACT_FriendshipEffectMsg_msgSeq = 0;
                seq = 1;
            }

            bool isEffectDone = scProc_ACT_FriendshipEffect(ref scProc_ACT_FriendshipEffectMsg_effSeq, args);
            bool isMsgDone;
            switch ((BtlStrType)args[2])
            {
                case BtlStrType.BTL_STRTYPE_SET:
                    unsafe
                    {
                        fixed (int* pArgs = args)
                        {
                            isMsgDone = scproc_msgSetCore(ref scProc_ACT_FriendshipEffectMsg_msgSeq, (ushort)args[3], pArgs + 4, args.Length - 4);
                        }
                    }
                    break;

                case BtlStrType.BTL_STRTYPE_STD:
                    unsafe
                    {
                        fixed (int* pArgs = args)
                        {
                            isMsgDone = scproc_msgStdCore(ref scProc_ACT_FriendshipEffectMsg_msgSeq, (ushort)args[3], pArgs + 4, args.Length - 4);
                        }
                    }
                    break;

                default:
                    isMsgDone = true;
                    break;
            }

            return isEffectDone & isMsgDone;
        }
