            byte pokeID = (byte)args[0];
            uint exp = (uint)args[1];
            uint effort_hp = (uint)args[2];
            uint effort_pow = (uint)args[3];
            uint effort_def = (uint)args[4];
            uint effort_sp_pow = (uint)args[5];
            uint effort_sp_def = (uint)args[6];
            uint effort_agi = (uint)args[7];
            int memberIdx = m_myParty.FindMemberByPokeID(pokeID);
            if (memberIdx >= 0)
            {
                m_viewExpGetDesc.pokeDesc[memberIdx].exp += exp;
                m_viewExpGetDesc.pokeDesc[memberIdx].effort_hp += effort_hp;
                m_viewExpGetDesc.pokeDesc[memberIdx].effort_pow += effort_pow;
                m_viewExpGetDesc.pokeDesc[memberIdx].effort_def += effort_def;
                m_viewExpGetDesc.pokeDesc[memberIdx].effort_sp_pow += effort_sp_pow;
                m_viewExpGetDesc.pokeDesc[memberIdx].effort_sp_def += effort_sp_def;
                m_viewExpGetDesc.pokeDesc[memberIdx].effort_agi += effort_agi;
            }

            return true;
        }
		private bool scProc_ACT_Exp(ref int seq, int[] args) {
            switch (seq)
            {
                case 0:
                    m_viewExpGetResult.Clear();
                    m_viewCore.CMD_ExpGet_Start(m_viewExpGetDesc, m_viewExpGetResult);
                    seq++;
                    return false;

                case 1:
                    if (!m_viewCore.CMD_ExpGet_Wait(m_viewExpGetResult))
                        return false;

                    updatePokeParamByLevelUp(m_viewExpGetResult);
                    seq++;
                    return false;

                default:
                    return true;
            }
        }
		private void updatePokeParamByLevelUp(in global::Dpr.Battle.Logic.BattleViewBase.ExpGetResult result) {
            BTL_PARTY party = getPokeCon().GetPartyData(m_myID);
            for (int i = 0; i < party.GetMemberCount(); i++)
            {
                BTL_POKEPARAM bpp = party.GetMemberData((byte)i);
                if (!result.isLevelUpOccurred[i])
                    continue;

                m_mainModule.NotifyPokemonLevelup(bpp);
                if (copyWaza(bpp.GetSrcData(), m_viewExpGetDesc.iPtrParty.GetMemberPointerConst((uint)i)))
                {
                    bpp.ReflectByPP();
                    m_mainModule.ReflectPokeWazaOboe(bpp.GetID());
                }

                if (result.isDeviceUpDown)
                    m_mainModule.NotifyTurnedLevelUpPokePos(bpp.GetID());
            }
        }
		private bool copyWaza(global::Pml.PokePara.PokemonParam pDest, global::Pml.PokePara.PokemonParam pSrc) {
            bool isChanged = false;
            for (byte i = 0; i < PmlConstants.MAX_WAZA_NUM; i++)
            {
                WazaNo waza = pSrc.GetWazaNo(i);
                if (waza != pDest.GetWazaNo(i))
                {
                    pDest.SetWaza(i, waza);
                    isChanged = true;
                }
            }

            return isChanged;
        }
