		private bool scProc_ACT_BallThrow(ref int seq, int[] args) {
            BtlPokePos targetPos = (BtlPokePos)args[1];
            bool fSuccess = args[3] != 0;
            _ = args[6];
            switch (seq)
            {
                case (int)SeqscProc_ACT_BallThrow.SEQ_START_BALL_THROW:
                {
                    BtlvPos userVpos = m_mainModule.BtlPosToViewPos((BtlPokePos)args[0]);
                    BtlvPos targetVpos = m_mainModule.BtlPosToViewPos(targetPos);
                    m_viewCore.CMD_EFFECT_BallThrow(userVpos, targetVpos, (ItemNo)args[6], (byte)args[2], fSuccess, args[5] != 0);
                    seq = (int)SeqscProc_ACT_BallThrow.SEQ_WAIT_BALL_THROW;
                    return false;
                }

                case (int)SeqscProc_ACT_BallThrow.SEQ_WAIT_BALL_THROW:
                    if (m_viewCore.CMD_EFFECT_WaitBallThrow())
                        seq = (int)SeqscProc_ACT_BallThrow.SEQ_DONE;
                    return false;

                case (int)SeqscProc_ACT_BallThrow.SEQ_DONE:
                    if (fSuccess)
                        m_mainModule.NotifyPokemonGetToGameSystem(getPokeCon().GetFrontPokeDataConst(targetPos));
                    return true;

                default:
                    return true;
            }
        }
