		private bool scProc_ACT_BallThrowForbidden(ref int seq, int[] args) {
            BtlPokePos pos = (BtlPokePos)args[0];
            _ = args[2];
            switch (seq)
            {
                case (int)SeqscProc_ACT_BallThrowForbidden.SEQ_START:
                    seq = m_mainModule.IsSkyBattle()
                        ? (int)SeqscProc_ACT_BallThrowForbidden.SEQ_MSG_START
                        : (int)SeqscProc_ACT_BallThrowForbidden.SEQ_BALLTHROW_START;
                    return false;

                case (int)SeqscProc_ACT_BallThrowForbidden.SEQ_BALLTHROW_START:
                {
                    BtlvPos vpos = m_mainModule.BtlPosToViewPos(pos);
                    m_viewCore.CMD_EFFECT_BallThrowTrainer(vpos, (ItemNo)args[2]);
                    seq++;
                    return false;
                }

                case (int)SeqscProc_ACT_BallThrowForbidden.SEQ_BALLTHROW_WAIT:
                    if (m_viewCore.CMD_EFFECT_WaitBallThrowTrainer())
                        seq++;
                    return false;

                case (int)SeqscProc_ACT_BallThrowForbidden.SEQ_MSG_START:
                    switch ((byte)args[1])
                    {
                        case 0:
                            BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.BallThrowTrainer);
                            break;

                        case 1:
                        {
                            BTL_POKEPARAM bpp = getPokeCon().GetFrontPokeDataConst(pos);
                            BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.BallThrowLevelCap);
                            BTLV_STRPARAM.AddArg(m_strParam, bpp.GetID());
                            break;
                        }

                        default:
                            seq = (int)SeqscProc_ACT_BallThrowForbidden.SEQ_END;
                            return false;
                    }

                    m_viewCore.CMD_StartMsg(m_strParam);
                    seq++;
                    return false;

                case (int)SeqscProc_ACT_BallThrowForbidden.SEQ_MSG_WAIT:
                    if (m_viewCore.CMD_WaitMsg())
                        seq++;
                    return false;

                case (int)SeqscProc_ACT_BallThrowForbidden.SEQ_END:
                    return true;

                default:
                    return false;
            }
        }
		private bool scProc_ACTOP_ChangeTokusei(ref int seq, int[] args) {
            byte pokeID = (byte)args[0];
            BtlPokePos pos = m_mainModule.PokeIDtoPokePos(getPokeCon(), pokeID);
            switch (seq)
            {
                case 0:
                    if (IsChapterSkipMode())
                    {
                        getPokeCon().GetPokeParam(pokeID).ChangeTokusei((TokuseiNo)args[1]);
                        return true;
                    }

                    m_viewCore.CMD_TokWin_DispStart(pos, false);
                    seq++;
                    return false;

                case 1:
                    if (!m_viewCore.CMD_TokWin_DispWait(pos))
                        return false;

                    getPokeCon().GetPokeParam(pokeID).ChangeTokusei((TokuseiNo)args[1]);
                    m_viewCore.CMD_TokWin_Renew_Start(pos);
                    seq++;
                    return false;

                case 2:
                    if (!m_viewCore.CMD_TokWin_Renew_Wait(pos))
                        return false;

                    notifyTokuseiToAI(pokeID);
                    seq++;
                    return false;

                default:
                    return true;
            }
        }
		private bool scProc_ACTOP_SwapTokusei(ref int seq, int[] args) {
            byte pokeID1 = (byte)args[0];
            byte pokeID2 = (byte)args[1];
            TokuseiNo tokusei1 = (TokuseiNo)args[2];
            TokuseiNo tokusei2 = (TokuseiNo)args[3];
            BtlPokePos pos1 = m_mainModule.PokeIDtoPokePos(getPokeCon(), pokeID1);
            BtlPokePos pos2 = m_mainModule.PokeIDtoPokePos(getPokeCon(), pokeID2);
            BTL_POKEPARAM bpp1 = getPokeCon().GetPokeParam(pokeID1);
            BTL_POKEPARAM bpp2 = getPokeCon().GetPokeParam(pokeID2);
            switch (seq)
            {
                case 0:
                    if (IsChapterSkipMode() || m_mainModule.IsFriendPokeID(pokeID1, pokeID2))
                    {
                        bpp1.ChangeTokusei(tokusei1);
                        bpp2.ChangeTokusei(tokusei2);
                        return true;
                    }

                    m_viewCore.CMD_TokWin_DispStart(pos1, false);
                    scProc_ACTOP_SwapTokusei_timer = 8;
                    seq++;
                    return false;

                case 1:
                    m_viewCore.CMD_TokWin_DispWait(pos1);
                    if (scProc_ACTOP_SwapTokusei_timer != 0)
                    {
                        scProc_ACTOP_SwapTokusei_timer--;
                        return false;
                    }

                    m_viewCore.CMD_TokWin_DispStart(pos2, false);
                    seq++;
                    return false;

                case 2:
                {
                    bool isDone1 = m_viewCore.CMD_TokWin_DispWait(pos1);
                    bool isDone2 = m_viewCore.CMD_TokWin_DispWait(pos2);
                    if (isDone1 && isDone2)
                        seq++;
                    return false;
                }

                case 3:
                    bpp1.ChangeTokusei(tokusei1);
                    bpp2.ChangeTokusei(tokusei2);
                    scProc_ACTOP_SwapTokusei_timer = 0;
                    seq++;
                    return false;

                case 4:
                    scProc_ACTOP_SwapTokusei_timer++;
                    if (scProc_ACTOP_SwapTokusei_timer < 9)
                        return false;

                    m_viewCore.CMD_TokWin_Renew_Start(pos1);
                    seq++;
                    return false;

                case 5:
                    if (!m_viewCore.CMD_TokWin_Renew_Wait(pos1))
                        return false;

                    m_viewCore.CMD_TokWin_Renew_Start(pos2);
                    seq++;
                    return false;

                case 6:
                    if (!m_viewCore.CMD_TokWin_Renew_Wait(pos2))
                        return false;

                    notifyTokuseiToAI(pokeID1);
                    notifyTokuseiToAI(pokeID2);
                    scProc_ACTOP_SwapTokusei_timer = 0;
                    seq++;
                    return false;

                case 7:
                    scProc_ACTOP_SwapTokusei_timer++;
                    if (scProc_ACTOP_SwapTokusei_timer < 9)
                        return false;

                    m_viewCore.CMD_QuitTokWin(pos1);
                    m_viewCore.CMD_QuitTokWin(pos2);
                    seq++;
                    return false;

                case 8:
                {
                    bool isDone1 = m_viewCore.CMD_QuitTokWinWait(pos1);
                    bool isDone2 = m_viewCore.CMD_QuitTokWinWait(pos2);
                    if (isDone1 && isDone2)
                        seq++;
                    return false;
                }

                default:
                    return true;
            }
        }
