		private bool scProc_ACT_Safari(ref int seq, int[] args) {
            byte pokeID = (byte)args[0];
            byte cmd = (byte)args[1];
            byte flag = (byte)args[2];
            switch (seq)
            {
                case (int)Seq_ACT_Safari.Start:
                    if (cmd == 2)
                    {
                        seq = (int)Seq_ACT_Safari.Yousumi0;
                        goto case (int)Seq_ACT_Safari.Yousumi0;
                    }

                    if (cmd > 1)
                    {
                        seq = (int)Seq_ACT_Safari.End;
                        return true;
                    }

                    seq = (int)Seq_ACT_Safari.Throw0;
                    goto case (int)Seq_ACT_Safari.Throw0;

                case (int)Seq_ACT_Safari.Throw0:
                {
                    ushort strID = cmd != 0 ? (ushort)BTL_STRID_STD.SafariZoneDoroMsg1 : (ushort)BTL_STRID_STD.SafariZoneEsaMsg1;
                    byte clientID = MainModule.PokeIDtoClientID(pokeID);
                    BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, strID);
                    BTLV_STRPARAM.AddArg(m_strParam, clientID);
                    BTLV_STRPARAM.AddArg(m_strParam, 12);
                    m_viewCore.CMD_StartMsg(m_strParam);
                    seq = (int)Seq_ACT_Safari.Throw1;
                    return false;
                }

                case (int)Seq_ACT_Safari.Throw1:
                {
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    seq = (int)Seq_ACT_Safari.Throw2;
                    BtlPokePos pos = m_mainModule.PokeIDtoPokePos(getPokeCon(), pokeID);
                    m_viewCore.CMD_ACT_Safari_Start(pos, cmd != 0 ? BattleViewBase.SafariCmd.Doro : BattleViewBase.SafariCmd.Esa, flag != 0 ? 1 : 0);
                    goto case (int)Seq_ACT_Safari.Throw2;
                }

                case (int)Seq_ACT_Safari.Throw2:
                {
                    if (!m_viewCore.CMD_ACT_Safari_Wait())
                        return false;

                    ushort strID;
                    if (cmd == 0)
                        strID = flag != 0 ? (ushort)BTL_STRID_STD.SafariZoneEsaMsg3 : (ushort)BTL_STRID_STD.SafariZoneEsaMsg2;
                    else
                        strID = flag != 0 ? (ushort)BTL_STRID_STD.SafariZoneDoroMsg3 : (ushort)BTL_STRID_STD.SafariZoneDoroMsg2;

                    BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, strID);
                    BTLV_STRPARAM.AddArg(m_strParam, 12);
                    m_viewCore.CMD_StartMsg(m_strParam);
                    seq = (int)Seq_ACT_Safari.Throw3;
                    return false;
                }

                case (int)Seq_ACT_Safari.Throw3:
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    seq = (int)Seq_ACT_Safari.End;
                    return true;

                case (int)Seq_ACT_Safari.Yousumi0:
                    BTLV_STRPARAM.Setup(m_strParam, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.SafariZoneYousumiMsg);
                    BTLV_STRPARAM.AddArg(m_strParam, 12);
                    m_viewCore.CMD_StartMsg(m_strParam);
                    seq = (int)Seq_ACT_Safari.Yousumi1;
                    return false;

                case (int)Seq_ACT_Safari.Yousumi1:
                {
                    if (!m_viewCore.CMD_WaitMsg())
                        return false;

                    BtlPokePos pos = m_mainModule.PokeIDtoPokePos(getPokeCon(), pokeID);
                    m_viewCore.CMD_ACT_Safari_Start(pos, BattleViewBase.SafariCmd.Yousumi, 0);
                    seq = (int)Seq_ACT_Safari.Yousumi2;
                    return false;
                }

                case (int)Seq_ACT_Safari.Yousumi2:
                    if (!m_viewCore.CMD_ACT_Safari_Wait())
                        return false;

                    seq = (int)Seq_ACT_Safari.End;
                    return true;

                case (int)Seq_ACT_Safari.End:
                    return true;

                default:
                    return false;
            }
        }
		public bool CanChangePoke(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp) {
            if (!m_mainModule.IsCompetitorScenarioMode())
                return true;

            if (string.IsNullOrEmpty(m_mainModule.GetCliehtTrainerSequence(m_myID, TrainerSequenceID.SEQUENCE_LAST_POKE_IN)))
                return true;

            PokemonParam srcParam = bpp.GetSrcDataConst();
            PokeParty party = m_mainModule.GetBattleSetupParam().party[m_myID];
            PokemonParam lastMember = party.GetMemberPointerConst(party.GetMemberCount() - 1);
            if (srcParam.GetID() != lastMember.GetID())
                return true;

            return srcParam.GetMonsNo() != lastMember.GetMonsNo();
        }
