			public void Dispose() { }
			public VariableArgs() {
                Clear();
            }
			public void Clear() {
                m_cnt = 0;
                for (int i = 0; i < m_args.Length; i++)
                    m_args[i] = 0;
            }
			public void Setup(int[] cmd_args) {
                m_cnt = (byte)cmd_args[0];
                if (m_cnt < m_args.Length && m_cnt != 0)
                {
                    for (int i = 0; i < m_cnt; i++)
                        m_args[i] = cmd_args[i + 1];
                }
            }
			public byte GetCount() {
                return m_cnt;
            }
			public int GetArg(byte idx) {
                if (idx >= m_args.Length)
                    return 0;

                return m_args[idx];
            }
		}
