		private sealed class FriendshipEffectProc
		{
			private global::Dpr.Battle.Logic.MainModule m_mainModule;
			private global::Dpr.Battle.Logic.POKECON m_pokeCon;
			private global::Dpr.Battle.Logic.BattleViewBase m_viewCore;
			private byte m_myID;
			private byte m_numCoverPos;
			private byte m_searchIdx;
			private int m_step;
			public FriendshipEffectProc() {
                m_mainModule = null;
                m_pokeCon = null;
                m_viewCore = null;
                m_myID = 5;
                m_numCoverPos = 0;
                m_searchIdx = 0;
                m_step = -1;
            }
			public void Dispose() { }
			public void Start(global::Dpr.Battle.Logic.MainModule mainModule, global::Dpr.Battle.Logic.POKECON pokeCon, global::Dpr.Battle.Logic.BattleViewBase viewCore, byte myID, byte numCoverPos) {
                m_mainModule = mainModule;
                m_pokeCon = pokeCon;
                m_viewCore = viewCore;
                m_numCoverPos = numCoverPos;
                m_myID = myID;
                m_step = 0;
                m_searchIdx = 0;
            }
			public bool Wait() {
                if (m_mainModule.GetRule() == BtlRule.BTL_RULE_SAFARI)
                    return true;

                switch (m_step)
                {
                    case 0:
                        while (m_searchIdx < m_numCoverPos)
                        {
                            BTL_POKEPARAM bpp = m_pokeCon.GetClientPokeDataConst(m_myID, m_searchIdx++);
                            if (!S_IsEnable(bpp))
                                continue;

                            int effectNo = checkEffectNo(bpp);
                            if (effectNo < 0)
                                continue;

                            BtlvPos vpos = m_mainModule.PokeIDtoViewPos(m_pokeCon, bpp.GetID());
                            m_viewCore.CMD_AddEffectByPos(vpos, (BtlEff)effectNo);
                            m_step++;
                            break;
                        }

                        if (m_step == 0)
                            return true;

                        break;

                    case 1:
                        if (m_viewCore.CMD_WaitEffectByPos())
                            m_step = 0;

                        break;

                    default:
                        return true;
                }

                return false;
            }
			private int checkEffectNo(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp) {
                byte friendship = m_mainModule.GetPokeFriendship(bpp);
                if (friendship == 255)
                    return (int)BtlEff.BTLEFF_KAWAIGARI_TURN;

                if (friendship >= 220)
                    return (int)BtlEff.BTLEFF_KAWAIGARI_JUMP;

                if (friendship >= 180)
                    return (int)BtlEff.BTLEFF_KAWAIGARI_SHAKE;

                return -1;
            }
			public static bool S_IsEnable(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp) {
                if (bpp == null)
                    return false;

                if (bpp.IsDead())
                    return false;

                if (bpp.CheckNemuri(BTL_POKEPARAM.NemuriCheckMode.NEMURI_CHECK_ONLY_SICK))
                    return false;

                return !bpp.CheckSick(WazaSick.WAZASICK_KOORI);
            }
		}
